(361106,40123,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'14 misafir için masayı önceden ..., kilit bir misafirperverlik kilometre taşı.'::text,'kurdurdu'::text,'kurdurdu'::text,'kurarak'::text,'14 misafir için masayı önceden kurdurdu, kilit bir misafirperverlik kilometre taşı.'::text),
(361107,40123,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'14 vendég számára előre ... az asztalt, ami kulcsfontosságú mérföldkő a vendégszeretetben.'::text,'megteríttette'::text,'megteríttette'::text,'terítve'::text,'14 vendég számára előre megteríttette az asztalt, ami kulcsfontosságú mérföldkő a vendégszeretetben.'::text),
(361110,40124,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der jüngste Gast wünscht sich, dass die Gastfreundschaft an diesem Tisch das ganze Jahr ...'::text,'anhalten würde'::text,'anhalten wird'::text,'anhält'::text,'Der jüngste Gast wünscht sich, dass die Gastfreundschaft an diesem Tisch das ganze Jahr anhalten würde.'::text),
(361114,40124,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Наймолодший гість хоче, щоб гостинність за цим столом ... цілий рік.'::text,'тривала'::text,'триватиме'::text,'триває'::text,'Наймолодший гість хоче, щоб гостинність за цим столом тривала цілий рік.'::text),
(361113,40124,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El invitado más joven desea que la hospitalidad de esta mesa ... todo el año.'::text,'durara'::text,'durará'::text,'dura'::text,'El invitado más joven desea que la hospitalidad de esta mesa durara todo el año.'::text),
(361112,40124,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le plus jeune invité aimerait que l''hospitalité de cette table ... toute l''année.'::text,'dure'::text,'durera'::text,'dure'::text,'Le plus jeune invité aimerait que l''hospitalité de cette table dure toute l''année.'::text),
(361115,40124,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En genç misafir, bu sofradaki misafirperverliğin bütün yıl ... istiyor.'::text,'sürmesini'::text,'süreceğini'::text,'sürdüğünü'::text,'En genç misafir, bu sofradaki misafirperverliğin bütün yıl sürmesini istiyor.'::text),
(361116,40124,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A legfiatalabb vendég azt szeretné, ha a vendégszeretet ennél az asztalnál egész évben ...'::text,'tartana'::text,'tart majd'::text,'tart'::text,'A legfiatalabb vendég azt szeretné, ha a vendégszeretet ennél az asztalnál egész évben tartana.'::text),
(361119,40125,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Großmutter, ... Gastfreundschaft typischerweise mit Tee beginnt, füllt jedes Glas selbst.'::text,'deren'::text,'die'::text,'welche'::text,'Die Großmutter, deren Gastfreundschaft typischerweise mit Tee beginnt, füllt jedes Glas selbst.'::text),
(361123,40125,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бабуся, ... гостинність зазвичай починається з чаю, сама наповнює кожну склянку.'::text,'чия'::text,'яка'::text,'котра'::text,'Бабуся, чия гостинність зазвичай починається з чаю, сама наповнює кожну склянку.'::text),
(361122,40125,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La abuela, ... hospitalidad normalmente empieza con té, llena cada vaso ella misma.'::text,'cuya'::text,'quien'::text,'la cual'::text,'La abuela, cuya hospitalidad normalmente empieza con té, llena cada vaso ella misma.'::text),
(361121,40125,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La grand-mère, ... l''hospitalité commence généralement par le thé, remplit elle-même chaque verre.'::text,'dont'::text,'qui'::text,'laquelle'::text,'La grand-mère, dont l''hospitalité commence généralement par le thé, remplit elle-même chaque verre.'::text),
(361124,40125,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Büyükanne, ... misafirperverliği genellikle çayla başlar, her bardağı kendisi doldurur.'::text,'ki onun'::text,'ki'::text,'ki'::text,'Büyükanne, ki onun misafirperverliği genellikle çayla başlar, her bardağı kendisi doldurur.'::text),
(361125,40125,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A nagymama, ... vendégszeretete jellemzően teával kezdődik, maga tölt meg minden poharat.'::text,'akinek a'::text,'aki'::text,'amely'::text,'A nagymama, akinek a vendégszeretete jellemzően teával kezdődik, maga tölt meg minden poharat.'::text),
(361128,40126,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... dieser Familie gibt jedem Gast das Gefühl, zu Hause zu sein.'::text,'Die Gastfreundschaft'::text,'Eine Gastfreundschaft'::text,'Gastfreundschaft'::text,'Die Gastfreundschaft dieser Familie gibt jedem Gast das Gefühl, zu Hause zu sein.'::text),
(361132,40126,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... цієї родини дає кожному гостеві відчуття, що він удома.'::text,'Гостинність'::text,'Гостинність'::text,'Гостинність'::text,'Гостинність цієї родини дає кожному гостеві відчуття, що він удома.'::text),
(361131,40126,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... de esta familia hace que cada invitado se sienta como en casa.'::text,'La hospitalidad'::text,'Una hospitalidad'::text,'Hospitalidad'::text,'La hospitalidad de esta familia hace que cada invitado se sienta como en casa.'::text),
(361130,40126,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... de cette famille fait que chaque invité se sent chez lui.'::text,'L''hospitalité'::text,'Une hospitalité'::text,'Hospitalité'::text,'L''hospitalité de cette famille fait que chaque invité se sent chez lui.'::text),
(361133,40126,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu ailenin ... her misafire kendini evinde gibi hissettiriyor.'::text,'misafirperverliği'::text,'bir misafirperverliği'::text,'misafirperverliği'::text,'Bu ailenin misafirperverliği her misafire kendini evinde gibi hissettiriyor.'::text),
(361134,40126,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ennek a családnak ... eléri, hogy minden vendég otthon érezze magát.'::text,'a vendégszeretete'::text,'egy vendégszeretete'::text,'vendégszeretete'::text,'Ennek a családnak a vendégszeretete eléri, hogy minden vendég otthon érezze magát.'::text),
(361137,40127,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... des kleinen Blockhauses füllt die Gastfreundschaft der Familie den ganzen Tisch.'::text,'Trotz'::text,'Aufgrund'::text,'Im Fall'::text,'Trotz des kleinen Blockhauses füllt die Gastfreundschaft der Familie den ganzen Tisch.'::text),
(361141,40127,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... маленький зруб, гостинність родини заповнює весь стіл.'::text,'Попри'::text,'Завдяки'::text,'У разі'::text,'Попри маленький зруб, гостинність родини заповнює весь стіл.'::text),
(361140,40127,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... la pequeña casa de troncos, la hospitalidad de la familia llena toda la mesa.'::text,'A pesar de'::text,'Debido a'::text,'En caso de'::text,'A pesar de la pequeña casa de troncos, la hospitalidad de la familia llena toda la mesa.'::text),
(361139,40127,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... la petite maison en rondins, l''hospitalité de la famille remplit toute la table.'::text,'Malgré'::text,'En raison de'::text,'En cas de'::text,'Malgré la petite maison en rondins, l''hospitalité de la famille remplit toute la table.'::text),
(361142,40127,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Küçük kütük eve ..., ailenin misafirperverliği bütün sofrayı dolduruyor.'::text,'rağmen'::text,'sayesinde'::text,'durumunda'::text,'Küçük kütük eve rağmen, ailenin misafirperverliği bütün sofrayı dolduruyor.'::text),
(361143,40127,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A kis gerendaház ..., a család vendégszeretete megtölti az egész asztalt.'::text,'ellenére'::text,'miatt'::text,'esetén'::text,'A kis gerendaház ellenére, a család vendégszeretete megtölti az egész asztalt.'::text),
(361146,40128,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Gäste wussten, dass die Großmutter sie mit großer Gastfreundschaft ...'::text,'empfangen würde'::text,'empfangen wird'::text,'empfängt'::text,'Die Gäste wussten, dass die Großmutter sie mit großer Gastfreundschaft empfangen würde.'::text),
(361150,40128,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Гості знали, що бабуся ... їх із великою гостинністю.'::text,'зустріне'::text,'зустріне'::text,'зустрічає'::text,'Гості знали, що бабуся зустріне їх із великою гостинністю.'::text),
(361149,40128,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Los invitados sabían que la abuela los ... con gran hospitalidad.'::text,'recibiría'::text,'recibirá'::text,'recibe'::text,'Los invitados sabían que la abuela los recibiría con gran hospitalidad.'::text),
(361148,40128,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les invités savaient que la grand-mère les ... avec une grande hospitalité.'::text,'accueillerait'::text,'accueillera'::text,'accueille'::text,'Les invités savaient que la grand-mère les accueillerait avec une grande hospitalité.'::text),
(361151,40128,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Misafirler büyükannenin onları büyük bir misafirperverlikle ... biliyordu.'::text,'karşılayacağını'::text,'karşılayacağını'::text,'karşıladığını'::text,'Misafirler büyükannenin onları büyük bir misafirperverlikle karşılayacağını biliyordu.'::text),
(361152,40128,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A vendégek tudták, hogy a nagymama nagy vendégszeretettel ... őket.'::text,'fogadja majd'::text,'fogadja'::text,'fogadja'::text,'A vendégek tudták, hogy a nagymama nagy vendégszeretettel fogadja majd őket.'::text),
(361155,40129,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rate mal, sie hat gesagt, Oma ... seit sechs Tee aus dem Samowar ein. Totale Gastfreundschaft.'::text,'schenkt'::text,'schenkt'::text,'schenkt'::text,'Rate mal, sie hat gesagt, Oma schenkt seit sechs Tee aus dem Samowar ein. Totale Gastfreundschaft.'::text),
(361159,40129,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Уяви, вона сказала, що бабуся ... чай із того самовара з шостої. Повна гостинність.'::text,'наливає'::text,'наливає'::text,'наливає'::text,'Уяви, вона сказала, що бабуся наливає чай із того самовара з шостої. Повна гостинність.'::text),
(361158,40129,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Adivina qué, dijo que la abuela ... té de ese samovar desde las seis. Hospitalidad total.'::text,'lleva sirviendo'::text,'está sirviendo'::text,'sirve'::text,'Adivina qué, dijo que la abuela lleva sirviendo té de ese samovar desde las seis. Hospitalidad total.'::text),
(361157,40129,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Devine quoi, elle a dit que mamie ... du thé de ce samovar depuis six heures. L''hospitalité totale.'::text,'sert'::text,'sert'::text,'sert'::text,'Devine quoi, elle a dit que mamie sert du thé de ce samovar depuis six heures. L''hospitalité totale.'::text),
(361160,40129,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tahmin et ne oldu, büyükannenin altıdan beri o semaverden çay ... söyledi. Tam misafirperverlik.'::text,'doldurduğunu'::text,'doldurduğunu'::text,'doldurduğunu'::text,'Tahmin et ne oldu, büyükannenin altıdan beri o semaverden çay doldurduğunu söyledi. Tam misafirperverlik.'::text),
(361161,40129,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Képzeld, azt mondta, hogy a nagyi hat óta ... a teát abból a szamovárból. Teljes vendégszeretet.'::text,'tölti'::text,'tölti'::text,'tölti'::text,'Képzeld, azt mondta, hogy a nagyi hat óta tölti a teát abból a szamovárból. Teljes vendégszeretet.'::text),
(361164,40130,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Leicht großzügige Gastfreundschaft: Als sie anstießen, hatte Oma schon vierzig Gläser Tee ...'::text,'gefüllt'::text,'gefüllt'::text,'gefüllt'::text,'Leicht großzügige Gastfreundschaft: Als sie anstießen, hatte Oma schon vierzig Gläser Tee gefüllt.'::text),
(361168,40130,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Трохи щедра гостинність: поки вони цокнулися, бабуся ... сорок склянок чаю.'::text,'наповнила'::text,'наповнила'::text,'наповнювала'::text,'Трохи щедра гостинність: поки вони цокнулися, бабуся наповнила сорок склянок чаю.'::text),
(361167,40130,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hospitalidad ligeramente generosa: para cuando brindaron, la abuela ... cuarenta vasos de té.'::text,'había llenado'::text,'ha llenado'::text,'estaba llenando'::text,'Hospitalidad ligeramente generosa: para cuando brindaron, la abuela había llenado cuarenta vasos de té.'::text),
(361166,40130,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hospitalité légèrement généreuse : quand ils ont trinqué, mamie ... quarante verres de thé.'::text,'avait rempli'::text,'a rempli'::text,'remplissait'::text,'Hospitalité légèrement généreuse : quand ils ont trinqué, mamie avait rempli quarante verres de thé.'::text),
(361169,40130,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hafif cömert misafirperverlik: onlar bardak tokuşturana kadar büyükanne kırk bardak çay ...'::text,'doldurmuştu'::text,'doldurdu'::text,'dolduruyordu'::text,'Hafif cömert misafirperverlik: onlar bardak tokuşturana kadar büyükanne kırk bardak çay doldurmuştu.'::text),
(361170,40130,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Enyhén bőkezű vendégszeretet: mire koccintottak, a nagyi negyven pohár teát ...'::text,'töltött meg'::text,'töltött meg'::text,'töltött'::text,'Enyhén bőkezű vendégszeretet: mire koccintottak, a nagyi negyven pohár teát töltött meg.'::text),
(361173,40131,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ein kleines bisschen zu viel Gastfreundschaft: Bis Mitternacht wird Oma jeden Gast mindestens zehnmal ...'::text,'gefüttert haben'::text,'füttern'::text,'füttern'::text,'Ein kleines bisschen zu viel Gastfreundschaft: Bis Mitternacht wird Oma jeden Gast mindestens zehnmal gefüttert haben.'::text),
(361177,40131,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Трохи забагато гостинності: до півночі бабуся ... кожного гостя щонайменше десять разів.'::text,'нагодує'::text,'годуватиме'::text,'годує'::text,'Трохи забагато гостинності: до півночі бабуся нагодує кожного гостя щонайменше десять разів.'::text),
(361176,40131,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hospitalidad un pelín excesiva: para medianoche, la abuela ... a cada invitado al menos diez veces.'::text,'habrá dado de comer'::text,'dará de comer'::text,'da de comer'::text,'Hospitalidad un pelín excesiva: para medianoche, la abuela habrá dado de comer a cada invitado al menos diez veces.'::text),
(361175,40131,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Un poil trop d''hospitalité : d''ici minuit, mamie ... chaque invité au moins dix fois.'::text,'aura nourri'::text,'nourrira'::text,'nourrit'::text,'Un poil trop d''hospitalité : d''ici minuit, mamie aura nourri chaque invité au moins dix fois.'::text),
(361178,40131,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Birazcık fazla misafirperverlik: gece yarısına kadar büyükanne her misafiri en az on kez ...'::text,'doyurmuş olacak'::text,'doyuracak'::text,'doyuruyor'::text,'Birazcık fazla misafirperverlik: gece yarısına kadar büyükanne her misafiri en az on kez doyurmuş olacak.'::text),
(361179,40131,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kicsit túl sok vendégszeretet: éjfélig a nagyi minden vendéget legalább tízszer ...'::text,'megetet'::text,'megetet'::text,'eteti'::text,'Kicsit túl sok vendégszeretet: éjfélig a nagyi minden vendéget legalább tízszer megetet.'::text),
(403977,44887,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Morgen um diese Zeit ... ich wieder auf dieser Jacht, und niemand kann mich aufhalten!'::text,'segle'::text,'segle'::text,'segle'::text,'Morgen um diese Zeit segle ich wieder auf dieser Jacht, und niemand kann mich aufhalten!'::text),
(403981,44887,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Завтра о цій порі я знову ... на тій яхті, і ніхто мене не зупинить!'::text,'плаватиму'::text,'попливу'::text,'пливу'::text,'Завтра о цій порі я знову плаватиму на тій яхті, і ніхто мене не зупинить!'::text),
(403980,44887,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mañana a esta hora ... otra vez en ese yate, ¡y nadie me puede detener!'::text,'estaré navegando'::text,'navegaré'::text,'navego'::text,'Mañana a esta hora estaré navegando otra vez en ese yate, ¡y nadie me puede detener!'::text),
(403979,44887,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Demain à cette heure-ci, je ... de nouveau sur ce yacht, et personne ne peut m''arrêter !'::text,'naviguerai'::text,'naviguerai'::text,'navigue'::text,'Demain à cette heure-ci, je naviguerai de nouveau sur ce yacht, et personne ne peut m''arrêter !'::text),
(403982,44887,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yarın bu saatte yine o yatta ... ve kimse beni durduramaz!'::text,'yelken açıyor olacağım'::text,'yelken açacağım'::text,'yelken açarım'::text,'Yarın bu saatte yine o yatta yelken açıyor olacağım ve kimse beni durduramaz!'::text),
(403983,44887,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Holnap ilyenkor újra azon a jachton ..., és senki sem állíthat meg!'::text,'fogok vitorlázni'::text,'vitorlázom'::text,'vitorlázom'::text,'Holnap ilyenkor újra azon a jachton fogok vitorlázni, és senki sem állíthat meg!'::text),
(403986,44888,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ich schwöre, diese Jacht wird schneller als der Wind ..., sonst ist alles verloren!'::text,'segeln'::text,'segeln'::text,'segeln'::text,'Ich schwöre, diese Jacht wird schneller als der Wind segeln, sonst ist alles verloren!'::text),
(403990,44888,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Клянуся, ця яхта ... швидше за вітер, інакше все пропало!'::text,'попливе'::text,'пливтиме'::text,'пливе'::text,'Клянуся, ця яхта попливе швидше за вітер, інакше все пропало!'::text),
(403989,44888,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Te juro que este yate ... más rápido que el viento, o todo está perdido!'::text,'navegará'::text,'estará navegando'::text,'está navegando'::text,'¡Te juro que este yate navegará más rápido que el viento, o todo está perdido!'::text),
(403988,44888,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Je jure que ce yacht ... plus vite que le vent, sinon tout est perdu !'::text,'naviguera'::text,'naviguera'::text,'navigue'::text,'Je jure que ce yacht naviguera plus vite que le vent, sinon tout est perdu !'::text),
(403991,44888,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yemin ederim bu yat rüzgârdan hızlı ..., yoksa her şey biter!'::text,'gidecek'::text,'gidiyor olacak'::text,'gidiyor'::text,'Yemin ederim bu yat rüzgârdan hızlı gidecek, yoksa her şey biter!'::text),
(403992,44888,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Esküszöm, ez a jacht gyorsabban ... a szélnél, különben minden elveszett!'::text,'fog haladni'::text,'fog haladni'::text,'halad'::text,'Esküszöm, ez a jacht gyorsabban fog haladni a szélnél, különben minden elveszett!'::text),
(403995,44889,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn der Wind das Segel ..., wird die Jacht schneller.'::text,'füllt'::text,'füllte'::text,'füllen wird'::text,'Wenn der Wind das Segel füllt, wird die Jacht schneller.'::text),
(403999,44889,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коли вітер ... вітрило, яхта пришвидшується.'::text,'наповнює'::text,'наповнив'::text,'наповнить'::text,'Коли вітер наповнює вітрило, яхта пришвидшується.'::text),
(403998,44889,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si el viento ... la vela, el yate acelera.'::text,'llena'::text,'llenó'::text,'llenará'::text,'Si el viento llena la vela, el yate acelera.'::text),
(403997,44889,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si le vent ... la voile, le yacht accélère.'::text,'gonfle'::text,'a gonflé'::text,'gonflera'::text,'Si le vent gonfle la voile, le yacht accélère.'::text),
(404000,44889,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rüzgâr yelkeni ..., yat hızlanır.'::text,'doldurursa'::text,'doldurduysa'::text,'dolduracaksa'::text,'Rüzgâr yelkeni doldurursa, yat hızlanır.'::text),
(404001,44889,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a szél ... a vitorlát, a jacht felgyorsul.'::text,'megtölti'::text,'megtöltötte'::text,'megtölti majd'::text,'Ha a szél megtölti a vitorlát, a jacht felgyorsul.'::text),
(404004,44890,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rate mal, ich habe gehört, sie ... die Besitzerin der Jacht sein, aber keiner weiß es genau.'::text,'könnte'::text,'muss'::text,'kann nicht'::text,'Rate mal, ich habe gehört, sie könnte die Besitzerin der Jacht sein, aber keiner weiß es genau.'::text),
(404008,44890,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Уяви, я чула, що вона ... бути власницею яхти, але ніхто точно не знає.'::text,'може'::text,'мусить'::text,'не може'::text,'Уяви, я чула, що вона може бути власницею яхти, але ніхто точно не знає.'::text),
(404007,44890,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Adivina qué, oí que ... ser la dueña del yate, pero nadie lo sabe seguro.'::text,'podría'::text,'debe de'::text,'no puede'::text,'Adivina qué, oí que podría ser la dueña del yate, pero nadie lo sabe seguro.'::text),
(404006,44890,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Devine quoi, j''ai entendu qu''elle ... être la propriétaire du yacht, mais personne n''en est sûr.'::text,'pourrait'::text,'doit'::text,'ne peut pas'::text,'Devine quoi, j''ai entendu qu''elle pourrait être la propriétaire du yacht, mais personne n''en est sûr.'::text),
(404009,44890,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tahmin et ne oldu, duyduğuma göre yatın sahibi ..., ama kimse kesin bilmiyor.'::text,'olabilirmiş'::text,'olmalıymış'::text,'olamazmış'::text,'Tahmin et ne oldu, duyduğuma göre yatın sahibi olabilirmiş, ama kimse kesin bilmiyor.'::text),
(404010,44890,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Képzeld, azt hallottam, hogy ő ... a jacht tulajdonosa, de senki sem tudja biztosan.'::text,'lehet'::text,'biztosan'::text,'nem lehet'::text,'Képzeld, azt hallottam, hogy ő lehet a jacht tulajdonosa, de senki sem tudja biztosan.'::text),
(404022,44892,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie sagte, dass sie vor dieser Reise noch nie eine Jacht ...'::text,'gesegelt hatte'::text,'gesegelt hat'::text,'segelt'::text,'Sie sagte, dass sie vor dieser Reise noch nie eine Jacht gesegelt hatte.'::text),
(404026,44892,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона сказала, що до цієї поїздки ... на яхті.'::text,'ніколи не плавала'::text,'ніколи не плавала'::text,'ніколи не плаває'::text,'Вона сказала, що до цієї поїздки ніколи не плавала на яхті.'::text),
(404025,44892,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dijo que ... en un yate antes de este viaje.'::text,'nunca había navegado'::text,'nunca ha navegado'::text,'nunca navega'::text,'Dijo que nunca había navegado en un yate antes de este viaje.'::text),
(404024,44892,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle a dit qu''elle ... sur un yacht avant ce voyage.'::text,'n''avait jamais navigué'::text,'n''a jamais navigué'::text,'ne navigue jamais'::text,'Elle a dit qu''elle n''avait jamais navigué sur un yacht avant ce voyage.'::text),
(404027,44892,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu geziden önce hiç yatla ... söyledi.'::text,'yelken açmadığını'::text,'yelken açmadığını'::text,'yelken açmadığını'::text,'Bu geziden önce hiç yatla yelken açmadığını söyledi.'::text),
(404028,44892,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Azt mondta, hogy a mostani út előtt ... jachton.'::text,'még sosem vitorlázott'::text,'még sosem vitorlázott'::text,'sosem vitorlázik'::text,'Azt mondta, hogy a mostani út előtt még sosem vitorlázott jachton.'::text),
(404031,44893,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... Angst vor dem Wasser, bevor sie mit dieser Jacht gesegelt ist.'::text,'hatte früher'::text,'hatte früher'::text,'war es gewohnt'::text,'Sie hatte früher Angst vor dem Wasser, bevor sie mit dieser Jacht gesegelt ist.'::text),
(404035,44893,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона ... води, поки не поплавала на цій яхті.'::text,'раніше боялася'::text,'раніше боялася'::text,'звикла боятися'::text,'Вона раніше боялася води, поки не поплавала на цій яхті.'::text),
(404034,44893,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Antes de navegar en este yate, ... tenerle miedo al agua.'::text,'solía'::text,'solía'::text,'estaba acostumbrada a'::text,'Antes de navegar en este yate, solía tenerle miedo al agua.'::text),
(404033,44893,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Avant de naviguer sur ce yacht, elle ... peur de l''eau.'::text,'avait'::text,'avait'::text,'était habituée à avoir'::text,'Avant de naviguer sur ce yacht, elle avait peur de l''eau.'::text),
(404036,44893,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu yatla yelken açmadan önce sudan ...'::text,'korkardı'::text,'korkardı'::text,'korkmaya alışkındı'::text,'Bu yatla yelken açmadan önce sudan korkardı.'::text),
(404037,44893,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mielőtt ezzel a jachttal vitorlázott, ... a víztől.'::text,'régen félt'::text,'félni szokott'::text,'hozzá volt szokva a félelemhez'::text,'Mielőtt ezzel a jachttal vitorlázott, régen félt a víztől.'::text),
(404040,44894,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie zieht in Erwägung, die Jacht für 3 Kundentermine ...'::text,'zu mieten'::text,'zu mieten'::text,'zu mieten'::text,'Sie zieht in Erwägung, die Jacht für 3 Kundentermine zu mieten.'::text),
(404044,44894,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона розглядає можливість ... яхту для 3 зустрічей із клієнтами.'::text,'орендувати'::text,'орендувати'::text,'орендувати'::text,'Вона розглядає можливість орендувати яхту для 3 зустрічей із клієнтами.'::text),
(404043,44894,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Está considerando ... el yate para 3 reuniones con clientes.'::text,'alquilar'::text,'alquilar'::text,'alquilar'::text,'Está considerando alquilar el yate para 3 reuniones con clientes.'::text),
(404042,44894,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle envisage de ... le yacht pour 3 rendez-vous clients.'::text,'louer'::text,'louer'::text,'louer'::text,'Elle envisage de louer le yacht pour 3 rendez-vous clients.'::text),
(404045,44894,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'3 müşteri toplantısı için yatı ... düşünüyor.'::text,'kiralamayı'::text,'kiralamayı'::text,'kiralamayı'::text,'3 müşteri toplantısı için yatı kiralamayı düşünüyor.'::text),
(404046,44894,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Fontolgatja, hogy ... a jachtot 3 ügyféltalálkozóra.'::text,'kibérelje'::text,'kibérelje'::text,'kibérelje'::text,'Fontolgatja, hogy kibérelje a jachtot 3 ügyféltalálkozóra.'::text),
(404049,44895,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Jacht schwimmt, weil sie auf dem Wasser ist, ...?'::text,'oder'::text,'nicht wahr'::text,'oder etwa nicht'::text,'Die Jacht schwimmt, weil sie auf dem Wasser ist, oder?'::text),
(404053,44895,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Яхта пливе, бо вона на воді, ...?'::text,'правда'::text,'хіба ні'::text,'так'::text,'Яхта пливе, бо вона на воді, правда?'::text),
(404052,44895,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El yate flota porque está en el agua, ¿...?'::text,'verdad'::text,'no'::text,'no es cierto'::text,'El yate flota porque está en el agua, ¿verdad?'::text),
(404051,44895,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le yacht flotte parce qu''il est sur l''eau, ... ?'::text,'non'::text,'n''est-ce pas'::text,'pas vrai'::text,'Le yacht flotte parce qu''il est sur l''eau, non ?'::text),
(404054,44895,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yat suyun üstünde olduğu için yüzüyor, ...?'::text,'değil mi'::text,'değil mi'::text,'değil miydi'::text,'Yat suyun üstünde olduğu için yüzüyor, değil mi?'::text),
(404055,44895,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A jacht azért úszik, mert a vízen van, ...?'::text,'nem igaz'::text,'ugye'::text,'nem igaz'::text,'A jacht azért úszik, mert a vízen van, nem igaz?'::text),
(404058,44896,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Derzeit ... die Jacht an Geschwindigkeit, was typischerweise eintritt, wenn Wind das Segel füllt.'::text,'gewinnt'::text,'gewinnt'::text,'hat gewonnen'::text,'Derzeit gewinnt die Jacht an Geschwindigkeit, was typischerweise eintritt, wenn Wind das Segel füllt.'::text),
(404062,44896,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Наразі яхта ... швидкість, що зазвичай відбувається, коли вітер наповнює вітрило.'::text,'набирає'::text,'набирає'::text,'набрала'::text,'Наразі яхта набирає швидкість, що зазвичай відбувається, коли вітер наповнює вітрило.'::text),
(404061,44896,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Actualmente, el yate ... velocidad, lo cual suele ocurrir cuando el viento llena la vela.'::text,'está ganando'::text,'gana'::text,'ha ganado'::text,'Actualmente, el yate está ganando velocidad, lo cual suele ocurrir cuando el viento llena la vela.'::text),
(404060,44896,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Actuellement, le yacht ... de la vitesse, ce qui se produit typiquement quand le vent gonfle la voile.'::text,'prend'::text,'prend'::text,'a pris'::text,'Actuellement, le yacht prend de la vitesse, ce qui se produit typiquement quand le vent gonfle la voile.'::text),
(404063,44896,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Şu anda yat hız ..., bu durum tipik olarak rüzgâr yelkeni doldurduğunda ortaya çıkar.'::text,'kazanıyor'::text,'kazanır'::text,'kazandı'::text,'Şu anda yat hız kazanıyor, bu durum tipik olarak rüzgâr yelkeni doldurduğunda ortaya çıkar.'::text),
(404064,44896,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Jelenleg a jacht ... sebességet, ami jellemzően akkor fordul elő, amikor a szél megtölti a vitorlát.'::text,'nyer'::text,'nyer'::text,'nyert'::text,'Jelenleg a jacht nyer sebességet, ami jellemzően akkor fordul elő, amikor a szél megtölti a vitorlát.'::text),
(368877,40987,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mädel, ich hab gehört, die Offiziere ... seit 5 Uhr morgens für diese Militärparade da.'::text,'stehen'::text,'stehen'::text,'stehen'::text,'Mädel, ich hab gehört, die Offiziere stehen seit 5 Uhr morgens für diese Militärparade da.'::text),
(368881,40987,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, я чула, що ті офіцери ... на цьому військовому параді з 5 ранку.'::text,'стоять'::text,'стоять'::text,'стоять'::text,'Подруго, я чула, що ті офіцери стоять на цьому військовому параді з 5 ранку.'::text),
(368880,40987,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tía, me han dicho que esos oficiales ... en este desfile militar desde las 5 de la mañana.'::text,'llevan de pie'::text,'están de pie'::text,'están de pie'::text,'Tía, me han dicho que esos oficiales llevan de pie en este desfile militar desde las 5 de la mañana.'::text),
(368879,40987,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Meuf, j''ai entendu que ces officiers ... pour ce défilé militaire depuis 5 h du matin.'::text,'sont debout'::text,'sont debout'::text,'sont debout'::text,'Meuf, j''ai entendu que ces officiers sont debout pour ce défilé militaire depuis 5 h du matin.'::text),
(368882,40987,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, duydum ki o subaylar sabah 5''ten beri bu askeri geçit töreni için ...'::text,'ayakta bekliyormuş'::text,'ayakta bekliyormuş'::text,'ayakta beklermiş'::text,'Kızım, duydum ki o subaylar sabah 5''ten beri bu askeri geçit töreni için ayakta bekliyormuş.'::text),
(368883,40987,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, azt hallottam, hogy azok a tisztek hajnali 5 óta ... ezen a katonai díszszemlén.'::text,'állnak'::text,'állnak'::text,'állnak'::text,'Csajszi, azt hallottam, hogy azok a tisztek hajnali 5 óta állnak ezen a katonai díszszemlén.'::text),
(368886,40988,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hör mal, angeblich hat ein Offizier geniest, während die Militärkapelle die Hymne ...'::text,'spielte'::text,'spielte'::text,'gespielt hat'::text,'Hör mal, angeblich hat ein Offizier geniest, während die Militärkapelle die Hymne spielte.'::text),
(368890,40988,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, кажуть, один офіцер чхнув, поки військовий оркестр ... гімн.'::text,'грав'::text,'зіграв'::text,'зіграв'::text,'Слухай, кажуть, один офіцер чхнув, поки військовий оркестр грав гімн.'::text),
(368889,40988,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, parece que un oficial estornudó mientras la banda militar ... el himno.'::text,'tocaba'::text,'tocó'::text,'ha tocado'::text,'Oye, parece que un oficial estornudó mientras la banda militar tocaba el himno.'::text),
(368888,40988,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute, apparemment un officier a éternué pendant que la fanfare militaire ... l''hymne.'::text,'jouait'::text,'a joué'::text,'a joué'::text,'Écoute, apparemment un officier a éternué pendant que la fanfare militaire jouait l''hymne.'::text),
(368891,40988,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, güya askeri bando milli marşı ... bir subay hapşırmış.'::text,'çalarken'::text,'çaldığında'::text,'çalmışken'::text,'Dinle, güya askeri bando milli marşı çalarken bir subay hapşırmış.'::text),
(368892,40988,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, állítólag az egyik tiszt tüsszentett, miközben a katonazenekar ... a himnuszt.'::text,'játszotta'::text,'eljátszotta'::text,'eljátszotta'::text,'Figyelj, állítólag az egyik tiszt tüsszentett, miközben a katonazenekar játszotta a himnuszt.'::text),
(368895,40989,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Also, er hat mir erzählt, dass er dieses Jahr bei drei Militärparaden ...'::text,'marschiert ist'::text,'marschiert ist'::text,'marschiert'::text,'Also, er hat mir erzählt, dass er dieses Jahr bei drei Militärparaden marschiert ist.'::text),
(368899,40989,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коротше, він сказав мені, що цього року ... на трьох військових парадах.'::text,'марширував'::text,'марширував'::text,'марширує'::text,'Коротше, він сказав мені, що цього року марширував на трьох військових парадах.'::text),
(368898,40989,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Vale, pues me dijo que este año ... en tres desfiles militares.'::text,'ha desfilado'::text,'ha estado desfilando'::text,'desfila'::text,'Vale, pues me dijo que este año ha desfilado en tres desfiles militares.'::text),
(368897,40989,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bon alors, il m''a dit qu''il ... dans trois défilés militaires cette année.'::text,'a défilé'::text,'a défilé'::text,'défile'::text,'Bon alors, il m''a dit qu''il a défilé dans trois défilés militaires cette année.'::text),
(368900,40989,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tamam, bak, bana bu yıl üç askeri geçit töreninde ... söyledi.'::text,'yürüdüğünü'::text,'yürüdüğünü'::text,'yürüdüğünü'::text,'Tamam, bak, bana bu yıl üç askeri geçit töreninde yürüdüğünü söyledi.'::text),
(368901,40989,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Szóval, azt mondta, hogy idén három katonai díszszemlén ...'::text,'menetelt'::text,'menetelt'::text,'menetel'::text,'Szóval, azt mondta, hogy idén három katonai díszszemlén menetelt.'::text),
(368904,40990,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Als die Menge ankam, hatten sich die Soldaten schon in militärischen Reihen auf dem Asphalt ...'::text,'aufgestellt'::text,'aufgestellt'::text,'aufgestellt'::text,'Als die Menge ankam, hatten sich die Soldaten schon in militärischen Reihen auf dem Asphalt aufgestellt.'::text),
(368908,40990,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коли прибув натовп, солдати вже ... військовими шеренгами на асфальті.'::text,'вишикувалися'::text,'вишикувалися'::text,'шикуються'::text,'Коли прибув натовп, солдати вже вишикувалися військовими шеренгами на асфальті.'::text),
(368907,40990,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cuando llegó el público, los soldados ya se ... en filas militares sobre el asfalto.'::text,'habían alineado'::text,'han alineado'::text,'alinean'::text,'Cuando llegó el público, los soldados ya se habían alineado en filas militares sobre el asfalto.'::text),
(368906,40990,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Quand la foule est arrivée, les soldats ... en rangs militaires sur le tarmac.'::text,'s''étaient alignés'::text,'se sont alignés'::text,'s''alignent'::text,'Quand la foule est arrivée, les soldats s''étaient alignés en rangs militaires sur le tarmac.'::text),
(368909,40990,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kalabalık geldiğinde askerler asfaltta askeri sıralar halinde çoktan ...'::text,'dizilmişti'::text,'dizildi'::text,'diziliyor'::text,'Kalabalık geldiğinde askerler asfaltta askeri sıralar halinde çoktan dizilmişti.'::text),
(368910,40990,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mire a tömeg megérkezett, a katonák már katonai sorokba ... az aszfalton.'::text,'álltak fel'::text,'álltak fel'::text,'állnak fel'::text,'Mire a tömeg megérkezett, a katonák már katonai sorokba álltak fel az aszfalton.'::text),
(368913,40991,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn der Offizier den Befehl gibt, ... die Militärparade sofort.'::text,'beginnt'::text,'würde beginnen'::text,'begann'::text,'Wenn der Offizier den Befehl gibt, beginnt die Militärparade sofort.'::text),
(368917,40991,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо офіцер дасть наказ, військовий парад ... одразу.'::text,'почнеться'::text,'почався б'::text,'почався'::text,'Якщо офіцер дасть наказ, військовий парад почнеться одразу.'::text),
(368916,40991,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si el oficial da la orden, el desfile militar ... de inmediato.'::text,'empezará'::text,'empezaría'::text,'empezó'::text,'Si el oficial da la orden, el desfile militar empezará de inmediato.'::text),
(368915,40991,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si l''officier donne l''ordre, le défilé militaire ... aussitôt.'::text,'commencera'::text,'commencerait'::text,'a commencé'::text,'Si l''officier donne l''ordre, le défilé militaire commencera aussitôt.'::text),
(368918,40991,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Subay emri verirse askeri geçit töreni hemen ...'::text,'başlayacak'::text,'başlardı'::text,'başladı'::text,'Subay emri verirse askeri geçit töreni hemen başlayacak.'::text),
(368919,40991,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a tiszt kiadja a parancsot, a katonai díszszemle azonnal ...'::text,'elkezdődik'::text,'elkezdődne'::text,'elkezdődött'::text,'Ha a tiszt kiadja a parancsot, a katonai díszszemle azonnal elkezdődik.'::text),
(368922,40992,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn es heute regnen würde, ... die Militärparade drinnen statt.'::text,'fände'::text,'findet'::text,'findet'::text,'Wenn es heute regnen würde, fände die Militärparade drinnen statt.'::text),
(368926,40992,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби сьогодні пішов дощ, військовий парад ... у приміщенні.'::text,'відбувся б'::text,'відбудеться'::text,'відбувається'::text,'Якби сьогодні пішов дощ, військовий парад відбувся б у приміщенні.'::text),
(368925,40992,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si hoy lloviera, el desfile militar ... bajo techo.'::text,'se celebraría'::text,'se celebrará'::text,'se celebra'::text,'Si hoy lloviera, el desfile militar se celebraría bajo techo.'::text),
(368924,40992,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'S''il pleuvait aujourd''hui, le défilé militaire ... à l''intérieur.'::text,'aurait lieu'::text,'aura lieu'::text,'a lieu'::text,'S''il pleuvait aujourd''hui, le défilé militaire aurait lieu à l''intérieur.'::text),
(368927,40992,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bugün yağmur yağsa, askeri geçit töreni içeride ...'::text,'yapılırdı'::text,'yapılacak'::text,'yapılıyor'::text,'Bugün yağmur yağsa, askeri geçit töreni içeride yapılırdı.'::text),
(368928,40992,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha ma esne az eső, a katonai díszszemlét bent ...'::text,'tartanák'::text,'tartják majd'::text,'tartják'::text,'Ha ma esne az eső, a katonai díszszemlét bent tartanák.'::text),
(368940,40994,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die militärische Formation ... aus Hunderten von Soldaten, die in geraden Blöcken stehen.'::text,'besteht'::text,'besteht'::text,'bestehend'::text,'Die militärische Formation besteht aus Hunderten von Soldaten, die in geraden Blöcken stehen.'::text),
(368944,40994,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Військове шикування ... із сотень солдатів, що стоять рівними блоками.'::text,'складається'::text,'складається'::text,'складаючись'::text,'Військове шикування складається із сотень солдатів, що стоять рівними блоками.'::text),
(368943,40994,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La formación militar ... de cientos de soldados de pie en bloques rectos.'::text,'consta'::text,'consta'::text,'constando'::text,'La formación militar consta de cientos de soldados de pie en bloques rectos.'::text),
(368942,40994,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La formation militaire ... de centaines de soldats debout en blocs droits.'::text,'se compose'::text,'se compose'::text,'se composant'::text,'La formation militaire se compose de centaines de soldats debout en blocs droits.'::text),
(368945,40994,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Askeri düzen, düz bloklar halinde duran yüzlerce askerden ...'::text,'oluşur'::text,'oluşur'::text,'oluşarak'::text,'Askeri düzen, düz bloklar halinde duran yüzlerce askerden oluşur.'::text),
(368946,40994,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A katonai alakzat egyenes tömbökben álló katonák százaiból ...'::text,'áll'::text,'áll'::text,'állva'::text,'A katonai alakzat egyenes tömbökben álló katonák százaiból áll.'::text),
(368949,40995,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie stehen seit Stunden in der Sonne; diese Militäroffiziere ... völlig erschöpft sein!'::text,'müssen'::text,'können nicht'::text,'dürfen nicht'::text,'Sie stehen seit Stunden in der Sonne; diese Militäroffiziere müssen völlig erschöpft sein!'::text),
(368953,40995,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вони стоять на сонці вже кілька годин; ці військові офіцери ... бути геть виснажені!'::text,'мусять'::text,'не можуть'::text,'не повинні'::text,'Вони стоять на сонці вже кілька годин; ці військові офіцери мусять бути геть виснажені!'::text),
(368952,40995,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Llevan horas al sol; ¡estos oficiales militares ... estar agotadísimos!'::text,'deben de'::text,'no pueden'::text,'no deben'::text,'Llevan horas al sol; ¡estos oficiales militares deben de estar agotadísimos!'::text),
(368951,40995,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ils sont au soleil depuis des heures ; ces officiers militaires ... être complètement épuisés !'::text,'doivent'::text,'ne peuvent pas'::text,'ne doivent pas'::text,'Ils sont au soleil depuis des heures ; ces officiers militaires doivent être complètement épuisés !'::text),
(368954,40995,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Saatlerdir güneşte duruyorlar; bu askeri subaylar kesinlikle ...!'::text,'bitkin olmalı'::text,'bitkin olamaz'::text,'bitkin olmamalı'::text,'Saatlerdir güneşte duruyorlar; bu askeri subaylar kesinlikle bitkin olmalı!'::text),
(368955,40995,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Órák óta állnak a napon; ezek a katonatisztek ... teljesen kimerültek!'::text,'biztosan'::text,'nem lehetnek'::text,'nem szabad lenniük'::text,'Órák óta állnak a napon; ezek a katonatisztek biztosan teljesen kimerültek!'::text),
(368958,40996,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Offizier, ... allein vor den Militärblöcken steht, sieht absolut furchterregend aus!'::text,'der'::text,'welcher'::text,'dessen'::text,'Der Offizier, der allein vor den Militärblöcken steht, sieht absolut furchterregend aus!'::text),
(368962,40996,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Офіцер, ... стоїть сам перед військовими блоками, виглядає просто жахливо!'::text,'який'::text,'котрий'::text,'чий'::text,'Офіцер, який стоїть сам перед військовими блоками, виглядає просто жахливо!'::text),
(368961,40996,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡El oficial ... está solo delante de los bloques militares da muchísimo miedo!'::text,'que'::text,'el cual'::text,'cuyo'::text,'¡El oficial que está solo delante de los bloques militares da muchísimo miedo!'::text),
(368960,40996,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''officier ... se tient seul devant les blocs militaires a l''air absolument terrifiant !'::text,'qui'::text,'lequel'::text,'dont'::text,'L''officier qui se tient seul devant les blocs militaires a l''air absolument terrifiant !'::text),
(368963,40996,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Askeri blokların önünde tek başına ... subay kesinlikle korkunç görünüyor!'::text,'duran'::text,'duran'::text,'durduğu'::text,'Askeri blokların önünde tek başına duran subay kesinlikle korkunç görünüyor!'::text),
(368964,40996,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A tiszt, ... egyedül áll a katonai tömbök előtt, egyenesen félelmetesen néz ki!'::text,'aki'::text,'amely'::text,'akinek'::text,'A tiszt, aki egyedül áll a katonai tömbök előtt, egyenesen félelmetesen néz ki!'::text),
(368967,40997,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gestern sagte der Offizier, diese Militärparade ... seine letzte, und jetzt ist es für immer vorbei!'::text,'wäre'::text,'wird'::text,'ist'::text,'Gestern sagte der Offizier, diese Militärparade wäre seine letzte, und jetzt ist es für immer vorbei!'::text),
(368971,40997,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Учора офіцер сказав, що цей військовий парад ... його останнім, і тепер усе скінчено назавжди!'::text,'буде'::text,'буде'::text,'є'::text,'Учора офіцер сказав, що цей військовий парад буде його останнім, і тепер усе скінчено назавжди!'::text),
(368970,40997,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Ayer el oficial dijo que este desfile militar ... el último, y ahora se acabó para siempre!'::text,'sería'::text,'será'::text,'es'::text,'¡Ayer el oficial dijo que este desfile militar sería el último, y ahora se acabó para siempre!'::text),
(368969,40997,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hier, l''officier a dit que ce défilé militaire ... son dernier, et maintenant c''est fini pour toujours !'::text,'serait'::text,'sera'::text,'est'::text,'Hier, l''officier a dit que ce défilé militaire serait son dernier, et maintenant c''est fini pour toujours !'::text),
(368972,40997,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dün subay bu askeri geçit töreninin kendisinin sonuncusu ... söyledi ve şimdi her şey sonsuza dek bitti!'::text,'olacağını'::text,'olacağını'::text,'olduğunu'::text,'Dün subay bu askeri geçit töreninin kendisinin sonuncusu olacağını söyledi ve şimdi her şey sonsuza dek bitti!'::text),
(368973,40997,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tegnap a tiszt azt mondta, hogy ez a katonai díszszemle ... az utolsója, és most örökre vége!'::text,'lesz'::text,'lesz'::text,NULL::text,'Tegnap a tiszt azt mondta, hogy ez a katonai díszszemle lesz az utolsója, és most örökre vége!'::text),
(378624,42070,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, du versprichst, dass du nächstes Jahr in der ersten Reihe ..., und ich glaube dir.'::text,'stehen wirst'::text,'stehen wirst'::text,'stehst'::text,'Ehrlich, du versprichst, dass du nächstes Jahr in der ersten Reihe stehen wirst, und ich glaube dir.'::text),
(378628,42070,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, ти обіцяєш, що наступного року ... в першій шерензі, і я тобі вірю.'::text,'стоятимеш'::text,'стоятимеш'::text,'стоїш'::text,'Чесно, ти обіцяєш, що наступного року стоятимеш в першій шерензі, і я тобі вірю.'::text),
(378627,42070,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En serio, prometes que el año que viene ... en la primera fila, y te creo.'::text,'estarás'::text,'estarás'::text,'estás'::text,'En serio, prometes que el año que viene estarás en la primera fila, y te creo.'::text),
(378626,42070,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Franchement, tu promets que l''année prochaine tu ... au premier rang, et je te crois.'::text,'seras'::text,'seras'::text,'es'::text,'Franchement, tu promets que l''année prochaine tu seras au premier rang, et je te crois.'::text),
(378629,42070,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası, seneye ön sırada ... söz veriyorsun, ben de sana inanıyorum.'::text,'duracağına'::text,'duracağına'::text,'durduğuna'::text,'Açıkçası, seneye ön sırada duracağına söz veriyorsun, ben de sana inanıyorum.'::text),
(378630,42070,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, megígéred, hogy jövőre az első sorban ..., és én hiszek neked.'::text,'fogsz állni'::text,'fogsz állni'::text,'állsz'::text,'Őszintén, megígéred, hogy jövőre az első sorban fogsz állni, és én hiszek neked.'::text),
(378633,42071,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn sich ein Soldat bewegt, ... die ganze Reihe schief.'::text,'wirkt'::text,'wirkte'::text,'wird wirken'::text,'Wenn sich ein Soldat bewegt, wirkt die ganze Reihe schief.'::text),
(378637,42071,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо один солдат ворухнеться, уся шеренга ... кривою.'::text,'виглядає'::text,'виглядала'::text,'виглядатиме'::text,'Якщо один солдат ворухнеться, уся шеренга виглядає кривою.'::text),
(378636,42071,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si un soldado se mueve, toda la fila ... torcida.'::text,'se ve'::text,'se veía'::text,'se verá'::text,'Si un soldado se mueve, toda la fila se ve torcida.'::text),
(378635,42071,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si un soldat bouge, tout le rang ... de travers.'::text,'a l''air'::text,'avait l''air'::text,'aura l''air'::text,'Si un soldat bouge, tout le rang a l''air de travers.'::text),
(378638,42071,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bir asker kıpırdarsa bütün sıra eğri ...'::text,'görünür'::text,'göründü'::text,'görünecek'::text,'Bir asker kıpırdarsa bütün sıra eğri görünür.'::text),
(378639,42071,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha egy katona megmozdul, az egész sor ferdének ...'::text,'tűnik'::text,'tűnt'::text,'fog tűnni'::text,'Ha egy katona megmozdul, az egész sor ferdének tűnik.'::text),
(378642,42072,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Diese erste Reihe ... viel kürzer, aber jetzt stehen zwanzig Frauen darin.'::text,'war früher'::text,'war früher'::text,'war es gewohnt zu sein'::text,'Diese erste Reihe war früher viel kürzer, aber jetzt stehen zwanzig Frauen darin.'::text),
(378646,42072,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ця перша шеренга ... набагато коротшою, але тепер у ній двадцять жінок.'::text,'раніше була'::text,'колись бувала'::text,'звикла бути'::text,'Ця перша шеренга раніше була набагато коротшою, але тепер у ній двадцять жінок.'::text),
(378645,42072,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Esta primera fila ... ser mucho más corta, pero ahora tiene veinte mujeres.'::text,'solía'::text,'solía'::text,'estaba acostumbrada a'::text,'Esta primera fila solía ser mucho más corta, pero ahora tiene veinte mujeres.'::text),
(378644,42072,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ce premier rang ... beaucoup plus court, mais maintenant il compte vingt femmes.'::text,'était'::text,'était'::text,'avait l''habitude d''être'::text,'Ce premier rang était beaucoup plus court, mais maintenant il compte vingt femmes.'::text),
(378647,42072,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu ön sıra eskiden çok daha kısa ..., ama şimdi içinde yirmi kadın var.'::text,'olurdu'::text,'olurdu'::text,'olmaya alışkındı'::text,'Bu ön sıra eskiden çok daha kısa olurdu, ama şimdi içinde yirmi kadın var.'::text),
(378648,42072,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ez az első sor ... sokkal rövidebb, de most húsz nő áll benne.'::text,'régen volt'::text,'régen volt'::text,'hozzá volt szokva, hogy legyen'::text,'Ez az első sor régen volt sokkal rövidebb, de most húsz nő áll benne.'::text),
(378651,42073,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Jede Frau in der Reihe vermeidet es, ..., während die Kamera vorbeifährt.'::text,'sich zu bewegen'::text,'sich zu bewegen'::text,'sich zu bewegen'::text,'Jede Frau in der Reihe vermeidet es, sich zu bewegen, während die Kamera vorbeifährt.'::text),
(378655,42073,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Кожна жінка в шерензі уникає ..., поки проїжджає камера.'::text,'рухів'::text,'рухатися'::text,'рухатися'::text,'Кожна жінка в шерензі уникає рухів, поки проїжджає камера.'::text),
(378654,42073,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cada mujer de la fila evita ... mientras pasa la cámara.'::text,'moverse'::text,'moverse'::text,'moverse'::text,'Cada mujer de la fila evita moverse mientras pasa la cámara.'::text),
(378653,42073,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Chaque femme du rang évite de ... pendant que la caméra passe.'::text,'bouger'::text,'bouger'::text,'bouger'::text,'Chaque femme du rang évite de bouger pendant que la caméra passe.'::text),
(378656,42073,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sıradaki her kadın kamera geçerken ... kaçınıyor.'::text,'kıpırdamaktan'::text,'kıpırdamaktan'::text,'kıpırdamaktan'::text,'Sıradaki her kadın kamera geçerken kıpırdamaktan kaçınıyor.'::text),
(378657,42073,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A sorban minden nő kerüli a ..., amíg a kamera elhalad.'::text,'megmozdulást'::text,'megmozdulást'::text,'megmozdulást'::text,'A sorban minden nő kerüli a megmozdulást, amíg a kamera elhalad.'::text),
(378660,42074,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die erste Reihe steht ganz still, ...?'::text,'oder'::text,'nicht wahr'::text,'stimmt''s'::text,'Die erste Reihe steht ganz still, oder?'::text),
(378664,42074,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Перша шеренга стоїть зовсім нерухомо, ...?'::text,'правда'::text,'хіба ні'::text,'так'::text,'Перша шеренга стоїть зовсім нерухомо, правда?'::text),
(378663,42074,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La primera fila está muy quieta, ¿...?'::text,'verdad'::text,'no'::text,'sí'::text,'La primera fila está muy quieta, ¿verdad?'::text),
(378662,42074,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le premier rang reste parfaitement immobile, ... ?'::text,'non'::text,'n''est-ce pas'::text,'si'::text,'Le premier rang reste parfaitement immobile, non ?'::text),
(378665,42074,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ön sıra kıpırdamadan duruyor, ...?'::text,'değil mi'::text,'değil mi'::text,'öyle mi'::text,'Ön sıra kıpırdamadan duruyor, değil mi?'::text),
(378666,42074,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az első sor teljesen mozdulatlanul áll, ...?'::text,'ugye'::text,'nem igaz'::text,'igen'::text,'Az első sor teljesen mozdulatlanul áll, ugye?'::text),
(378669,42075,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Keine einzige Frau in der ersten Reihe hat sich bewegt! Und ...'::text,'die zweite Reihe auch nicht'::text,'die zweite Reihe auch nicht'::text,'die zweite Reihe auch'::text,'Keine einzige Frau in der ersten Reihe hat sich bewegt! Und die zweite Reihe auch nicht.'::text),
(378673,42075,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Жодна жінка в першій шерензі не ворухнулася! І ...'::text,'друга шеренга теж ні'::text,'друга шеренга теж ні'::text,'друга шеренга теж'::text,'Жодна жінка в першій шерензі не ворухнулася! І друга шеренга теж ні.'::text),
(378672,42075,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Ni una sola mujer de la primera fila se movió! Y ...'::text,'la segunda fila tampoco'::text,'la segunda fila tampoco'::text,'la segunda fila también'::text,'¡Ni una sola mujer de la primera fila se movió! Y la segunda fila tampoco.'::text),
(378671,42075,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Pas une seule femme du premier rang n''a bougé ! Et ...'::text,'le deuxième rang non plus'::text,'le deuxième rang non plus'::text,'le deuxième rang aussi'::text,'Pas une seule femme du premier rang n''a bougé ! Et le deuxième rang non plus.'::text),
(378674,42075,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ön sıradaki tek bir kadın bile kıpırdamadı! Ve ...'::text,'ikinci sıra da kıpırdamadı'::text,'ikinci sıra da kıpırdamadı'::text,'ikinci sıra da kıpırdadı'::text,'Ön sıradaki tek bir kadın bile kıpırdamadı! Ve ikinci sıra da kıpırdamadı.'::text),
(378675,42075,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az első sorban egyetlen nő sem mozdult meg! És ...'::text,'a második sor sem'::text,'a második sor sem'::text,'a második sor is'::text,'Az első sorban egyetlen nő sem mozdult meg! És a második sor sem.'::text),
(378678,42076,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis zum Ende der Parade wird diese Reihe drei Stunden in der brennenden Sonne ...!'::text,'gestanden haben'::text,'stehen'::text,'stehen'::text,'Bis zum Ende der Parade wird diese Reihe drei Stunden in der brennenden Sonne gestanden haben!'::text),
(378682,42076,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До кінця параду ця шеренга ... на пекучому сонці три години!'::text,'простоїть'::text,'стоятиме'::text,'стоятиме'::text,'До кінця параду ця шеренга простоїть на пекучому сонці три години!'::text),
(378681,42076,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Al final del desfile, esta fila ... tres horas bajo un sol abrasador!'::text,'habrá estado'::text,'estará'::text,'estará'::text,'¡Al final del desfile, esta fila habrá estado tres horas bajo un sol abrasador!'::text),
(378680,42076,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''ici la fin du défilé, ce rang ... trois heures sous un soleil brûlant !'::text,'sera resté'::text,'restera'::text,'restera'::text,'D''ici la fin du défilé, ce rang sera resté trois heures sous un soleil brûlant !'::text),
(378683,42076,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Geçit töreninin sonunda bu sıra kavurucu güneşte üç saat ...!'::text,'durmuş olacak'::text,'duracak'::text,'duruyor olacak'::text,'Geçit töreninin sonunda bu sıra kavurucu güneşte üç saat durmuş olacak!'::text),
(378684,42076,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A díszszemle végére ez a sor ... három órát a tűző napon!'::text,'végigáll'::text,'áll majd'::text,'állni fog'::text,'A díszszemle végére ez a sor végigáll három órát a tűző napon!'::text),
(378696,42078,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hör mal, ich hab gehört, die erste Reihe ... hier seit sieben Uhr morgens.'::text,'steht'::text,'steht'::text,'steht'::text,'Hör mal, ich hab gehört, die erste Reihe steht hier seit sieben Uhr morgens.'::text),
(378700,42078,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, я чула, що перша шеренга ... тут із сьомої ранку.'::text,'стоїть'::text,'стоїть'::text,'стоїть'::text,'Слухай, я чула, що перша шеренга стоїть тут із сьомої ранку.'::text),
(378699,42078,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, me han dicho que la primera fila ... aquí desde las siete de la mañana.'::text,'lleva de pie'::text,'está de pie'::text,'está de pie'::text,'Oye, me han dicho que la primera fila lleva de pie aquí desde las siete de la mañana.'::text),
(378698,42078,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute, j''ai entendu que le premier rang ... là depuis sept heures du matin.'::text,'est'::text,'est'::text,'est'::text,'Écoute, j''ai entendu que le premier rang est là depuis sept heures du matin.'::text),
(378701,42078,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, duydum ki ön sıra sabah yediden beri burada ...'::text,'duruyormuş'::text,'duruyormuş'::text,'dururmuş'::text,'Dinle, duydum ki ön sıra sabah yediden beri burada duruyormuş.'::text),
(378702,42078,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, azt hallottam, hogy az első sor reggel hét óta itt ...'::text,'áll'::text,'áll'::text,'áll'::text,'Figyelj, azt hallottam, hogy az első sor reggel hét óta itt áll.'::text),
(378705,42079,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mädel, sie hat mir erzählt, dass ihre Reihe vor der Parade wochenlang ...'::text,'geübt hatte'::text,'geübt hat'::text,'übt'::text,'Mädel, sie hat mir erzählt, dass ihre Reihe vor der Parade wochenlang geübt hatte.'::text),
(378709,42079,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, вона сказала мені, що її шеренга ... тижнями перед парадом.'::text,'тренувалася'::text,'тренувалася'::text,'тренується'::text,'Подруго, вона сказала мені, що її шеренга тренувалася тижнями перед парадом.'::text),
(378708,42079,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tía, me dijo que su fila ... durante semanas antes del desfile.'::text,'había estado ensayando'::text,'ha estado ensayando'::text,'está ensayando'::text,'Tía, me dijo que su fila había estado ensayando durante semanas antes del desfile.'::text),
(378707,42079,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Meuf, elle m''a dit que son rang ... pendant des semaines avant le défilé.'::text,'s''était entraîné'::text,'s''est entraîné'::text,'s''entraîne'::text,'Meuf, elle m''a dit que son rang s''était entraîné pendant des semaines avant le défilé.'::text),
(378710,42079,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, bana sırasının geçit töreninden önce haftalarca ... anlattı.'::text,'prova yaptığını'::text,'prova yaptığını'::text,'prova yaptığını'::text,'Kızım, bana sırasının geçit töreninden önce haftalarca prova yaptığını anlattı.'::text),
(378711,42079,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, azt mondta, hogy a sora hetekig ... a díszszemle előtt.'::text,'gyakorolt'::text,'gyakorolt'::text,'gyakorol'::text,'Csajszi, azt mondta, hogy a sora hetekig gyakorolt a díszszemle előtt.'::text),
(338421,37603,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... seit Stunden Frachtkisten ab, und absolut niemand kann sie aufhalten!'::text,'stempelt'::text,'stempelt'::text,'stempelt'::text,'Sie stempelt seit Stunden Frachtkisten ab, und absolut niemand kann sie aufhalten!'::text),
(338425,37603,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона ... ящики з вантажем уже кілька годин, і абсолютно ніхто не може її зупинити!'::text,'штампує'::text,'штампує'::text,'штампує'::text,'Вона штампує ящики з вантажем уже кілька годин, і абсолютно ніхто не може її зупинити!'::text),
(338424,37603,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Desde hace horas ... cajas de carga, y absolutamente nadie puede detenerla!'::text,'sella'::text,'está sellando'::text,'sella'::text,'¡Desde hace horas sella cajas de carga, y absolutamente nadie puede detenerla!'::text),
(338423,37603,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle ... des caisses de marchandises depuis des heures, et absolument personne ne peut l''arrêter !'::text,'tamponne'::text,'tamponne'::text,'tamponne'::text,'Elle tamponne des caisses de marchandises depuis des heures, et absolument personne ne peut l''arrêter !'::text),
(338426,37603,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Saatlerdir kargo sandıklarını ... ve kesinlikle kimse onu durduramıyor!'::text,'damgalıyor'::text,'damgalıyor'::text,'damgalar'::text,'Saatlerdir kargo sandıklarını damgalıyor ve kesinlikle kimse onu durduramıyor!'::text),
(338427,37603,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Órák óta ... a rakományos ládákat, és egyáltalán senki sem tudja megállítani!'::text,'pecsételi'::text,'pecsételi'::text,'pecsételi'::text,'Órák óta pecsételi a rakományos ládákat, és egyáltalán senki sem tudja megállítani!'::text),
(338439,37605,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Als die Kräne anliefen, hatte sie alle Frachtpapiere schon ...'::text,'abgestempelt'::text,'abgestempelt'::text,'abgestempelt'::text,'Als die Kräne anliefen, hatte sie alle Frachtpapiere schon abgestempelt.'::text),
(338443,37605,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коли крани запрацювали, вона вже ... всі папери на вантаж.'::text,'проштампувала'::text,'проштампувала'::text,'штампує'::text,'Коли крани запрацювали, вона вже проштампувала всі папери на вантаж.'::text),
(338442,37605,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cuando arrancaron las grúas, ya ... todos los papeles de la carga.'::text,'había sellado'::text,'ha sellado'::text,'sella'::text,'Cuando arrancaron las grúas, ya había sellado todos los papeles de la carga.'::text),
(338441,37605,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Quand les grues ont démarré, elle ... tous les papiers de la cargaison.'::text,'avait tamponné'::text,'a tamponné'::text,'tamponne'::text,'Quand les grues ont démarré, elle avait tamponné tous les papiers de la cargaison.'::text),
(338444,37605,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Vinçler çalışmaya başladığında tüm kargo evraklarını çoktan ...'::text,'damgalamıştı'::text,'damgaladı'::text,'damgalıyor'::text,'Vinçler çalışmaya başladığında tüm kargo evraklarını çoktan damgalamıştı.'::text),
(338445,37605,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mire a darukat elindították, ő már az összes rakománypapírt ...'::text,'lepecsételte'::text,'lepecsételte'::text,'pecsételi'::text,'Mire a darukat elindították, ő már az összes rakománypapírt lepecsételte.'::text),
(338448,37606,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Fehlt der Stempel, ... die Fracht das Terminal nicht.'::text,'verlässt'::text,'verließe'::text,'verließ'::text,'Fehlt der Stempel, verlässt die Fracht das Terminal nicht.'::text),
(338452,37606,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо немає печатки, вантаж не ... термінал.'::text,'покине'::text,'покинув би'::text,'покинув'::text,'Якщо немає печатки, вантаж не покине термінал.'::text),
(338451,37606,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si falta el sello, la carga ... la terminal.'::text,'no saldrá de'::text,'no saldría de'::text,'no salió de'::text,'Si falta el sello, la carga no saldrá de la terminal.'::text),
(338450,37606,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'S''il manque le tampon, la cargaison ... le terminal.'::text,'ne quittera pas'::text,'ne quitterait pas'::text,'n''a pas quitté'::text,'S''il manque le tampon, la cargaison ne quittera pas le terminal.'::text),
(338453,37606,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Damga eksikse kargo terminalden ...'::text,'çıkmayacak'::text,'çıkmazdı'::text,'çıkmadı'::text,'Damga eksikse kargo terminalden çıkmayacak.'::text),
(338454,37606,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha hiányzik a pecsét, a rakomány ... a terminált.'::text,'nem hagyja el'::text,'nem hagyná el'::text,'nem hagyta el'::text,'Ha hiányzik a pecsét, a rakomány nem hagyja el a terminált.'::text),
(338457,37607,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, wenn ich Fracht mit deinem Selbstbewusstsein prüfen würde, ... ich jede Kiste zweimal abstempeln.'::text,'würde'::text,'werde'::text,'stempelte'::text,'Ehrlich, wenn ich Fracht mit deinem Selbstbewusstsein prüfen würde, würde ich jede Kiste zweimal abstempeln.'::text),
(338461,37607,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, якби я перевіряв вантаж із твоєю впевненістю, я ... кожен ящик двічі.'::text,'штампував би'::text,'штампуватиму'::text,'штампував'::text,'Чесно, якби я перевіряв вантаж із твоєю впевненістю, я штампував би кожен ящик двічі.'::text),
(338460,37607,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En serio, si revisara la carga con tu seguridad, ... cada caja dos veces.'::text,'sellaría'::text,'sellaré'::text,'sellé'::text,'En serio, si revisara la carga con tu seguridad, sellaría cada caja dos veces.'::text),
(338459,37607,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Franchement, si je contrôlais la cargaison avec ton assurance, je ... chaque caisse deux fois.'::text,'tamponnerais'::text,'tamponnerai'::text,'tamponnais'::text,'Franchement, si je contrôlais la cargaison avec ton assurance, je tamponnerais chaque caisse deux fois.'::text),
(338462,37607,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası, kargoyu senin özgüveninle kontrol etsem her sandığı iki kez ...'::text,'damgalardım'::text,'damgalayacağım'::text,'damgaladım'::text,'Açıkçası, kargoyu senin özgüveninle kontrol etsem her sandığı iki kez damgalardım.'::text),
(338463,37607,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, ha a te magabiztosságoddal ellenőrizném a rakományt, minden ládát kétszer ...'::text,'lepecsételnék'::text,'lepecsételek'::text,'lepecsételtem'::text,'Őszintén, ha a te magabiztosságoddal ellenőrizném a rakományt, minden ládát kétszer lepecsételnék.'::text),
(338466,37608,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Jede Frachtkiste ... heute Morgen mit einem roten Stempel markiert.'::text,'wurde'::text,'wird'::text,'hat'::text,'Jede Frachtkiste wurde heute Morgen mit einem roten Stempel markiert.'::text),
(338470,37608,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Кожен ящик із вантажем ... червоною печаткою сьогодні вранці.'::text,'був позначений'::text,'позначений'::text,'позначив'::text,'Кожен ящик із вантажем був позначений червоною печаткою сьогодні вранці.'::text),
(338469,37608,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cada caja de carga ... con un sello rojo esta mañana.'::text,'fue marcada'::text,'es marcada'::text,'marcó'::text,'Cada caja de carga fue marcada con un sello rojo esta mañana.'::text),
(338468,37608,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Chaque caisse de marchandises ... d''un tampon rouge ce matin.'::text,'a été marquée'::text,'est marquée'::text,'a marqué'::text,'Chaque caisse de marchandises a été marquée d''un tampon rouge ce matin.'::text),
(338471,37608,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Her kargo sandığı bu sabah kırmızı bir damgayla ...'::text,'işaretlendi'::text,'işaretleniyor'::text,'işaretledi'::text,'Her kargo sandığı bu sabah kırmızı bir damgayla işaretlendi.'::text),
(338472,37608,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ma reggel minden rakományos ládát piros pecséttel ...'::text,'jelöltek meg'::text,'jelölnek meg'::text,'megjelölt'::text,'Ma reggel minden rakományos ládát piros pecséttel jelöltek meg.'::text),
(338475,37609,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Vorher haben die Hafenarbeiter die Frachtkisten auf dem Regal ...'::text,'aufgereiht'::text,'aufgereiht'::text,'aufreihend'::text,'Vorher haben die Hafenarbeiter die Frachtkisten auf dem Regal aufgereiht.'::text),
(338479,37609,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Раніше докери ... ящики з вантажем на стелажі.'::text,'вишикували'::text,'були вишикувані'::text,'шикуючи'::text,'Раніше докери вишикували ящики з вантажем на стелажі.'::text),
(338478,37609,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Antes, los estibadores ... las cajas de carga en el estante.'::text,'alinearon'::text,'fueron alineados'::text,'alineando'::text,'Antes, los estibadores alinearon las cajas de carga en el estante.'::text),
(338477,37609,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Plus tôt, les dockers ... les caisses de marchandises sur le rayonnage.'::text,'ont aligné'::text,'ont été alignés'::text,'alignant'::text,'Plus tôt, les dockers ont aligné les caisses de marchandises sur le rayonnage.'::text),
(338480,37609,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Daha önce liman işçileri kargo sandıklarını rafa ...'::text,'dizdi'::text,'dizildi'::text,'dizerek'::text,'Daha önce liman işçileri kargo sandıklarını rafa dizdi.'::text),
(338481,37609,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Korábban a dokkmunkások ... a rakományos ládákat a polcon.'::text,'sorba rendezték'::text,'sorba lettek rendezve'::text,'sorba rendezve'::text,'Korábban a dokkmunkások sorba rendezték a rakományos ládákat a polcon.'::text),
(338484,37610,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'So ein sanfter Stempel. Die Frachtpapiere ... jetzt genehmigt sein, ganz klar.'::text,'müssen'::text,'können nicht'::text,'sollten nicht'::text,'So ein sanfter Stempel. Die Frachtpapiere müssen jetzt genehmigt sein, ganz klar.'::text),
(338488,37610,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Така ніжна печатка. Папери на вантаж тепер ... бути схвалені, очевидно.'::text,'мусять'::text,'не можуть'::text,'не повинні'::text,'Така ніжна печатка. Папери на вантаж тепер мусять бути схвалені, очевидно.'::text),
(338487,37610,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Qué sello tan delicado. Los papeles de la carga ... estar aprobados ya, obviamente.'::text,'deben de'::text,'no pueden'::text,'no deberían'::text,'Qué sello tan delicado. Los papeles de la carga deben de estar aprobados ya, obviamente.'::text),
(338486,37610,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Quel tampon délicat. Les papiers de la cargaison ... être approuvés maintenant, évidemment.'::text,'doivent'::text,'ne peuvent pas'::text,'ne devraient pas'::text,'Quel tampon délicat. Les papiers de la cargaison doivent être approuvés maintenant, évidemment.'::text),
(338489,37610,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ne kadar nazik bir damga. Kargo evrakları artık onaylanmış ..., tabii ki.'::text,'olmalı'::text,'olamaz'::text,'olmamalı'::text,'Ne kadar nazik bir damga. Kargo evrakları artık onaylanmış olmalı, tabii ki.'::text),
(338490,37610,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Milyen gyengéd pecsét. A rakománypapírokat most már ... jóváhagyták, nyilván.'::text,'biztosan'::text,'biztosan nem'::text,'nem kellett volna'::text,'Milyen gyengéd pecsét. A rakománypapírokat most már biztosan jóváhagyták, nyilván.'::text),
(338493,37611,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Beamtin, ... jede Frachtkiste abstempelt, ist offensichtlich sehr entspannt.'::text,'die'::text,'welche'::text,'deren'::text,'Die Beamtin, die jede Frachtkiste abstempelt, ist offensichtlich sehr entspannt.'::text),
(338497,37611,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Службовиця, ... штампує кожен ящик із вантажем, очевидно, дуже розслаблена.'::text,'яка'::text,'котра'::text,'чия'::text,'Службовиця, яка штампує кожен ящик із вантажем, очевидно, дуже розслаблена.'::text),
(338496,37611,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La funcionaria ... sella cada caja de carga está obviamente muy relajada.'::text,'que'::text,'la cual'::text,'cuya'::text,'La funcionaria que sella cada caja de carga está obviamente muy relajada.'::text),
(338495,37611,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''agente ... tamponne chaque caisse de marchandises est évidemment très détendue.'::text,'qui'::text,'laquelle'::text,'dont'::text,'L''agente qui tamponne chaque caisse de marchandises est évidemment très détendue.'::text),
(338498,37611,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Her kargo sandığını ... görevli belli ki çok rahat.'::text,'damgalayan'::text,'damgalayan'::text,'damgaladığı'::text,'Her kargo sandığını damgalayan görevli belli ki çok rahat.'::text),
(338499,37611,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A tisztviselőnő, ... minden rakományos ládát lepecsétel, nyilvánvalóan nagyon laza.'::text,'aki'::text,'amely'::text,'akinek'::text,'A tisztviselőnő, aki minden rakományos ládát lepecsétel, nyilvánvalóan nagyon laza.'::text),
(338502,37612,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie sagte der Crew, die Fracht ... am Tag zuvor kontrolliert worden. Ein leicht entspannter Zeitplan.'::text,'sei'::text,'ist'::text,'wurde gerade'::text,'Sie sagte der Crew, die Fracht sei am Tag zuvor kontrolliert worden. Ein leicht entspannter Zeitplan.'::text),
(338506,37612,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона сказала екіпажу, що вантаж ... перевірений напередодні. Трохи розслаблений графік.'::text,'був'::text,'був'::text,'був'::text,'Вона сказала екіпажу, що вантаж був перевірений напередодні. Трохи розслаблений графік.'::text),
(338505,37612,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le dijo a la tripulación que la carga ... inspeccionada el día anterior. Un horario ligeramente relajado.'::text,'había sido'::text,'ha sido'::text,'estaba siendo'::text,'Le dijo a la tripulación que la carga había sido inspeccionada el día anterior. Un horario ligeramente relajado.'::text),
(338504,37612,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle a dit à l''équipage que la cargaison ... inspectée la veille. Un planning légèrement détendu.'::text,'avait été'::text,'a été'::text,'était en train d''être'::text,'Elle a dit à l''équipage que la cargaison avait été inspectée la veille. Un planning légèrement détendu.'::text),
(338507,37612,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mürettebata kargonun bir gün önce ... söyledi. Biraz rahat bir program.'::text,'denetlenmiş olduğunu'::text,'denetlendiğini'::text,'denetlenmekte olduğunu'::text,'Mürettebata kargonun bir gün önce denetlenmiş olduğunu söyledi. Biraz rahat bir program.'::text),
(338508,37612,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Azt mondta a legénységnek, hogy a rakományt ... előző nap. Kissé laza ütemterv.'::text,'átvizsgálták'::text,'átvizsgálták'::text,'éppen vizsgálták'::text,'Azt mondta a legénységnek, hogy a rakományt átvizsgálták előző nap. Kissé laza ütemterv.'::text),
(338511,37613,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... eine ruhige Frachtbeamtin, aber jetzt ist jeder Stempel eine totale Katastrophe!'::text,'war früher'::text,'war früher'::text,'ist es gewohnt zu sein'::text,'Sie war früher eine ruhige Frachtbeamtin, aber jetzt ist jeder Stempel eine totale Katastrophe!'::text),
(338515,37613,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Колись вона ... тихою службовицею з вантажів, але тепер кожна печатка — повна катастрофа!'::text,'була'::text,'бувала'::text,'звикла бути'::text,'Колись вона була тихою службовицею з вантажів, але тепер кожна печатка — повна катастрофа!'::text),
(338514,37613,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Antes ... ser una agente de carga tranquila, pero ahora cada sello es una catástrofe total!'::text,'solía'::text,'solía'::text,'está acostumbrada a'::text,'¡Antes solía ser una agente de carga tranquila, pero ahora cada sello es una catástrofe total!'::text),
(338513,37613,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Avant, elle ... une agente de fret tranquille, mais maintenant chaque tampon est une catastrophe totale !'::text,'était'::text,'était'::text,'a l''habitude d''être'::text,'Avant, elle était une agente de fret tranquille, mais maintenant chaque tampon est une catastrophe totale !'::text),
(338516,37613,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Eskiden sessiz bir kargo memuru ..., ama şimdi her damga tam bir felaket!'::text,'olurdu'::text,'olurdu'::text,'olmaya alışkın'::text,'Eskiden sessiz bir kargo memuru olurdu, ama şimdi her damga tam bir felaket!'::text),
(338517,37613,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Régen csendes rakománytisztviselő ..., de most minden pecsét totális katasztrófa!'::text,'volt'::text,'volt'::text,'szokott lenni'::text,'Régen csendes rakománytisztviselő volt, de most minden pecsét totális katasztrófa!'::text),
(349437,38827,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ... sich auf der Düne, als hinter ihm die Sonne unterging.'::text,'filmte'::text,'filmte'::text,'hat gefilmt'::text,'Er filmte sich auf der Düne, als hinter ihm die Sonne unterging.'::text),
(349441,38827,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він ... себе на дюні, коли за ним зайшло сонце.'::text,'знімав'::text,'зняв'::text,'зняв'::text,'Він знімав себе на дюні, коли за ним зайшло сонце.'::text),
(349440,38827,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Se ... en la duna cuando el sol se puso detrás de él.'::text,'estaba grabando'::text,'grabó'::text,'ha grabado'::text,'Se estaba grabando en la duna cuando el sol se puso detrás de él.'::text),
(349439,38827,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... sur la dune quand le soleil s''est couché derrière lui.'::text,'se filmait'::text,'s''est filmé'::text,'s''est filmé'::text,'Il se filmait sur la dune quand le soleil s''est couché derrière lui.'::text),
(349442,38827,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Arkasında güneş battığında kumulun üstünde kendini ...'::text,'çekiyordu'::text,'çekti'::text,'çekti'::text,'Arkasında güneş battığında kumulun üstünde kendini çekiyordu.'::text),
(349443,38827,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Éppen ... magát a dűnén, amikor mögötte lement a nap.'::text,'filmezte'::text,'lefilmezte'::text,'lefilmezte'::text,'Éppen filmezte magát a dűnén, amikor mögötte lement a nap.'::text),
(349446,38828,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ... seit einer Stunde auf dieser Düne und filmt sich. Ein leicht langes Selfie.'::text,'steht'::text,'steht'::text,'steht'::text,'Er steht seit einer Stunde auf dieser Düne und filmt sich. Ein leicht langes Selfie.'::text),
(349450,38828,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він ... на тій дюні вже годину й знімає себе. Трохи довге селфі.'::text,'стоїть'::text,'стоїть'::text,'стоїть'::text,'Він стоїть на тій дюні вже годину й знімає себе. Трохи довге селфі.'::text),
(349449,38828,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hace una hora que ... en esa duna, grabándose. Un selfie un poco largo.'::text,'está'::text,'está'::text,'está'::text,'Hace una hora que está en esa duna, grabándose. Un selfie un poco largo.'::text),
(349448,38828,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... sur cette dune depuis une heure, à se filmer. Un selfie légèrement long.'::text,'est'::text,'est'::text,'est'::text,'Il est sur cette dune depuis une heure, à se filmer. Un selfie légèrement long.'::text),
(349451,38828,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bir saattir o kumulda ..., kendini çekiyor. Biraz uzun bir selfie.'::text,'duruyor'::text,'duruyor'::text,'durur'::text,'Bir saattir o kumulda duruyor, kendini çekiyor. Biraz uzun bir selfie.'::text),
(349452,38828,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Egy órája ... azon a dűnén, és filmezi magát. Kissé hosszú szelfi.'::text,'áll'::text,'áll'::text,'áll'::text,'Egy órája áll azon a dűnén, és filmezi magát. Kissé hosszú szelfi.'::text),
(349455,38829,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Während er auf der roten Düne ..., ging die Sonne unter. Tolles Timing, offensichtlich.'::text,'lachte'::text,'lachte'::text,'gelacht hat'::text,'Während er auf der roten Düne lachte, ging die Sonne unter. Tolles Timing, offensichtlich.'::text),
(349459,38829,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Поки він ... на червоній дюні, сонце зайшло. Чудовий таймінг, очевидно.'::text,'сміявся'::text,'засміявся'::text,'засміявся'::text,'Поки він сміявся на червоній дюні, сонце зайшло. Чудовий таймінг, очевидно.'::text),
(349458,38829,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mientras ... en la duna roja, se puso el sol. Qué buen momento, obviamente.'::text,'se reía'::text,'se rio'::text,'se ha reído'::text,'Mientras se reía en la duna roja, se puso el sol. Qué buen momento, obviamente.'::text),
(349457,38829,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Pendant qu''il ... sur la dune rouge, le soleil s''est couché. Super timing, évidemment.'::text,'riait'::text,'a ri'::text,'a ri'::text,'Pendant qu''il riait sur la dune rouge, le soleil s''est couché. Super timing, évidemment.'::text),
(349460,38829,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O kırmızı kumulda ..., güneş battı. Harika zamanlama, belli ki.'::text,'gülerken'::text,'güldü'::text,'güldü'::text,'O kırmızı kumulda gülerken, güneş battı. Harika zamanlama, belli ki.'::text),
(349461,38829,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Miközben ... a vörös dűnén, lement a nap. Remek időzítés, nyilván.'::text,'nevetett'::text,'felnevetett'::text,'felnevetett'::text,'Miközben nevetett a vörös dűnén, lement a nap. Remek időzítés, nyilván.'::text),
(349464,38830,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er hat heute drei Dünen ... und jede gefilmt. Keine große Sache.'::text,'erklommen'::text,'erklommen'::text,'erklommen'::text,'Er hat heute drei Dünen erklommen und jede gefilmt. Keine große Sache.'::text),
(349468,38830,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Сьогодні він ... на три дюни й зняв кожну. Нічого особливого.'::text,'виліз'::text,'ліз'::text,'лізе'::text,'Сьогодні він виліз на три дюни й зняв кожну. Нічого особливого.'::text),
(349467,38830,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hoy ... tres dunas y ha grabado cada una. Nada del otro mundo.'::text,'ha subido'::text,'ha estado subiendo'::text,'está subiendo'::text,'Hoy ha subido tres dunas y ha grabado cada una. Nada del otro mundo.'::text),
(349466,38830,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... trois dunes aujourd''hui et les a toutes filmées. Pas de quoi en faire un plat.'::text,'a gravi'::text,'a gravi'::text,'gravit'::text,'Il a gravi trois dunes aujourd''hui et les a toutes filmées. Pas de quoi en faire un plat.'::text),
(349469,38830,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bugün üç kumula ... ve hepsini çekti. Çok da önemli değil.'::text,'tırmandı'::text,'tırmanıyordu'::text,'tırmanıyor'::text,'Bugün üç kumula tırmandı ve hepsini çekti. Çok da önemli değil.'::text),
(349470,38830,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ma három dűnére ..., és mindegyiket lefilmezte. Nem nagy ügy.'::text,'mászott fel'::text,'mászott'::text,'mászik fel'::text,'Ma három dűnére mászott fel, és mindegyiket lefilmezte. Nem nagy ügy.'::text),
(349473,38831,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Um Mitternacht wird er am Feuer ..., und die Düne wird für immer in der Dunkelheit verschwinden!'::text,'sitzen'::text,'sitzen'::text,'sitzen'::text,'Um Mitternacht wird er am Feuer sitzen, und die Düne wird für immer in der Dunkelheit verschwinden!'::text),
(349477,38831,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Опівночі він ... біля вогнища, а дюна назавжди зникне в темряві!'::text,'сидітиме'::text,'сяде'::text,'сидить'::text,'Опівночі він сидітиме біля вогнища, а дюна назавжди зникне в темряві!'::text),
(349476,38831,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡A medianoche ... junto al fuego, y la duna desaparecerá en la oscuridad para siempre!'::text,'estará sentado'::text,'se sentará'::text,'se sienta'::text,'¡A medianoche estará sentado junto al fuego, y la duna desaparecerá en la oscuridad para siempre!'::text),
(349475,38831,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'À minuit, il ... près du feu, et la dune disparaîtra dans l''obscurité pour toujours !'::text,'sera assis'::text,'s''assiéra'::text,'s''assoit'::text,'À minuit, il sera assis près du feu, et la dune disparaîtra dans l''obscurité pour toujours !'::text),
(349478,38831,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gece yarısı ateşin başında ... ve kumul sonsuza dek karanlıkta kaybolacak!'::text,'oturuyor olacak'::text,'oturacak'::text,'oturuyor'::text,'Gece yarısı ateşin başında oturuyor olacak ve kumul sonsuza dek karanlıkta kaybolacak!'::text),
(349479,38831,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Éjfélkor a tűz mellett ..., és a dűne örökre eltűnik a sötétben!'::text,'fog ülni'::text,'leül'::text,'ül'::text,'Éjfélkor a tűz mellett fog ülni, és a dűne örökre eltűnik a sötétben!'::text),
(349482,38832,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er schwört, dass er morgen wieder auf diese Düne ..., auch wenn es eine totale Katastrophe wird!'::text,'klettern wird'::text,'klettern wird'::text,'klettert'::text,'Er schwört, dass er morgen wieder auf diese Düne klettern wird, auch wenn es eine totale Katastrophe wird!'::text),
(349486,38832,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він клянеться, що завтра знову ... на ту дюну, навіть якщо це буде повна катастрофа!'::text,'вилізе'::text,'лізтиме'::text,'лізе'::text,'Він клянеться, що завтра знову вилізе на ту дюну, навіть якщо це буде повна катастрофа!'::text),
(349485,38832,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Jura que mañana ... esa duna otra vez, aunque sea un desastre total!'::text,'subirá'::text,'estará subiendo'::text,'sube'::text,'¡Jura que mañana subirá esa duna otra vez, aunque sea un desastre total!'::text),
(349484,38832,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il jure qu''il ... encore cette dune demain, même si c''est un désastre total !'::text,'gravira'::text,'gravira'::text,'gravit'::text,'Il jure qu''il gravira encore cette dune demain, même si c''est un désastre total !'::text),
(349487,38832,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yarın o kumula yine ... yemin ediyor, tam bir felaket olsa bile!'::text,'tırmanacağına'::text,'tırmanıyor olacağına'::text,'tırmandığına'::text,'Yarın o kumula yine tırmanacağına yemin ediyor, tam bir felaket olsa bile!'::text),
(349488,38832,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Esküszik, hogy holnap újra ... arra a dűnére, még ha totális katasztrófa is lesz!'::text,'felmászik'::text,'fel fog mászni'::text,'felmászik'::text,'Esküszik, hogy holnap újra felmászik arra a dűnére, még ha totális katasztrófa is lesz!'::text),
(349500,38834,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn er nach Sonnenuntergang auf der Düne bleibt, ... er die Sterne.'::text,'sieht'::text,'würde sehen'::text,'sah'::text,'Wenn er nach Sonnenuntergang auf der Düne bleibt, sieht er die Sterne.'::text),
(349504,38834,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо він залишиться на дюні після заходу сонця, то ... зорі.'::text,'побачить'::text,'побачив би'::text,'побачив'::text,'Якщо він залишиться на дюні після заходу сонця, то побачить зорі.'::text),
(349503,38834,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si se queda en la duna después del atardecer, ... las estrellas.'::text,'verá'::text,'vería'::text,'vio'::text,'Si se queda en la duna después del atardecer, verá las estrellas.'::text),
(349502,38834,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'S''il reste sur la dune après le coucher du soleil, il ... les étoiles.'::text,'verra'::text,'verrait'::text,'a vu'::text,'S''il reste sur la dune après le coucher du soleil, il verra les étoiles.'::text),
(349505,38834,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gün batımından sonra kumulda kalırsa yıldızları ...'::text,'görecek'::text,'görürdü'::text,'gördü'::text,'Gün batımından sonra kumulda kalırsa yıldızları görecek.'::text),
(349506,38834,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha naplemente után a dűnén marad, ... a csillagokat.'::text,'látni fogja'::text,'látná'::text,'látta'::text,'Ha naplemente után a dűnén marad, látni fogja a csillagokat.'::text),
(349509,38835,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, er ist lowkey besessen davon, auf dieser Düne Selfies zu ...'::text,'filmen'::text,'filmen'::text,'filmen'::text,'Bro, er ist lowkey besessen davon, auf dieser Düne Selfies zu filmen.'::text),
(349513,38835,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, він трохи одержимий ... селфі на тій дюні.'::text,'зйомкою'::text,'зйомкою'::text,'зйомкою'::text,'Бро, він трохи одержимий зйомкою селфі на тій дюні.'::text),
(349512,38835,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, está medio obsesionado con ... selfies en esa duna.'::text,'grabar'::text,'grabar'::text,'grabar'::text,'Bro, está medio obsesionado con grabar selfies en esa duna.'::text),
(349511,38835,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frérot, il est un peu obsédé à l''idée de ... des selfies sur cette dune.'::text,'filmer'::text,'filmer'::text,'filmer'::text,'Frérot, il est un peu obsédé à l''idée de filmer des selfies sur cette dune.'::text),
(349514,38835,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, o kumulda selfie ... hafiften takıntılı.'::text,'çekmeye'::text,'çekmeye'::text,'çekmeye'::text,'Kanka, o kumulda selfie çekmeye hafiften takıntılı.'::text),
(349515,38835,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, kicsit rá van kattanva, hogy szelfiket ... azon a dűnén.'::text,'filmezzen'::text,'filmezzen'::text,'filmezzen'::text,'Tesó, kicsit rá van kattanva, hogy szelfiket filmezzen azon a dűnén.'::text),
(349518,38836,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ... schon seit einer Woche durch die Dünen dieser Wüste.'::text,'reist'::text,'reist'::text,'reist'::text,'Er reist schon seit einer Woche durch die Dünen dieser Wüste.'::text),
(349522,38836,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він ... дюнами цієї пустелі вже тиждень.'::text,'мандрує'::text,'мандрує'::text,'мандрує'::text,'Він мандрує дюнами цієї пустелі вже тиждень.'::text),
(349521,38836,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hace una semana que ... por las dunas de este desierto.'::text,'viaja'::text,'está viajando'::text,'viaja'::text,'Hace una semana que viaja por las dunas de este desierto.'::text),
(349520,38836,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... à travers les dunes de ce désert depuis une semaine.'::text,'voyage'::text,'voyage'::text,'voyage'::text,'Il voyage à travers les dunes de ce désert depuis une semaine.'::text),
(349523,38836,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bir haftadır bu çölün kumulları arasında ...'::text,'seyahat ediyor'::text,'seyahat ediyor'::text,'seyahat eder'::text,'Bir haftadır bu çölün kumulları arasında seyahat ediyor.'::text),
(349524,38836,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Már egy hete ... ennek a sivatagnak a dűnéi között.'::text,'utazik'::text,'utazik'::text,'utazik'::text,'Már egy hete utazik ennek a sivatagnak a dűnéi között.'::text),
(403059,44785,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis zum Sonnenuntergang wird dein Falke seine Flügel zehnmal auf deinem Handschuh ..., Respekt.'::text,'ausgebreitet haben'::text,'ausbreiten'::text,'ausbreiten'::text,'Bis zum Sonnenuntergang wird dein Falke seine Flügel zehnmal auf deinem Handschuh ausgebreitet haben, Respekt.'::text),
(403063,44785,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До заходу сонця твій сокіл ... крила на твоїй рукавиці десять разів, респект.'::text,'розправить'::text,'розправлятиме'::text,'розправлятиме'::text,'До заходу сонця твій сокіл розправить крила на твоїй рукавиці десять разів, респект.'::text),
(403062,44785,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para el atardecer, tu halcón ... las alas sobre tu guante diez veces, mis respetos.'::text,'habrá desplegado'::text,'desplegará'::text,'estará desplegando'::text,'Para el atardecer, tu halcón habrá desplegado las alas sobre tu guante diez veces, mis respetos.'::text),
(403061,44785,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''ici le coucher du soleil, ton faucon ... ses ailes sur ton gant dix fois, respect.'::text,'aura déployé'::text,'déploiera'::text,'déploiera'::text,'D''ici le coucher du soleil, ton faucon aura déployé ses ailes sur ton gant dix fois, respect.'::text),
(403064,44785,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gün batımına kadar şahinin kanatlarını eldiveninin üstünde on kez ..., saygılar.'::text,'açmış olacak'::text,'açacak'::text,'açıyor olacak'::text,'Gün batımına kadar şahinin kanatlarını eldiveninin üstünde on kez açmış olacak, saygılar.'::text),
(403065,44785,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Naplementéig a sólymod tízszer ... a szárnyait a kesztyűdön, le a kalappal.'::text,'kitárja'::text,'kitárja'::text,'tárja ki'::text,'Naplementéig a sólymod tízszer kitárja a szárnyait a kesztyűdön, le a kalappal.'::text),
(403068,44786,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gute Arbeit, Falke: Wären seine Flügel noch breiter gewesen, ... er ihm das Kopftuch heruntergeschlagen.'::text,'hätte'::text,'wird'::text,'hat'::text,'Gute Arbeit, Falke: Wären seine Flügel noch breiter gewesen, hätte er ihm das Kopftuch heruntergeschlagen.'::text),
(403072,44786,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чудова робота, соколе: якби його крила були ще ширші, він ... йому хустку з голови.'::text,'збив би'::text,'зіб''є'::text,'збив'::text,'Чудова робота, соколе: якби його крила були ще ширші, він збив би йому хустку з голови.'::text),
(403071,44786,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Buen trabajo, halcón: si sus alas hubieran sido un poco más anchas, le ... el pañuelo.'::text,'habría tirado'::text,'tirará'::text,'tiró'::text,'Buen trabajo, halcón: si sus alas hubieran sido un poco más anchas, le habría tirado el pañuelo.'::text),
(403070,44786,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bravo, le faucon : si ses ailes avaient été un peu plus larges, il lui ... son foulard.'::text,'aurait fait tomber'::text,'fera tomber'::text,'a fait tomber'::text,'Bravo, le faucon : si ses ailes avaient été un peu plus larges, il lui aurait fait tomber son foulard.'::text),
(403073,44786,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Aferin şahin: kanatları biraz daha geniş olsaydı adamın başörtüsünü ...'::text,'düşürmüş olurdu'::text,'düşürecek'::text,'düşürdü'::text,'Aferin şahin: kanatları biraz daha geniş olsaydı adamın başörtüsünü düşürmüş olurdu.'::text),
(403074,44786,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Szép munka, sólyom: ha a szárnyai még szélesebbek lettek volna, ... a fejkendőjét.'::text,'leverte volna'::text,'leveri'::text,'leverte'::text,'Szép munka, sólyom: ha a szárnyai még szélesebbek lettek volna, leverte volna a fejkendőjét.'::text),
(403077,44787,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er stritt ab, sich nervös ..., als die Flügel auf ihn zukamen, ganz klar.'::text,'gefühlt zu haben'::text,'zu fühlen'::text,'fühlte'::text,'Er stritt ab, sich nervös gefühlt zu haben, als die Flügel auf ihn zukamen, ganz klar.'::text),
(403081,44787,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він заперечив, що ... нервово, коли крила летіли на нього, очевидно.'::text,'почувався'::text,'почуватися'::text,'почувався'::text,'Він заперечив, що почувався нервово, коли крила летіли на нього, очевидно.'::text),
(403080,44787,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Negó ... nervioso cuando las alas fueron hacia él, obviamente.'::text,'sentirse'::text,'sentirse'::text,'se sintió'::text,'Negó sentirse nervioso cuando las alas fueron hacia él, obviamente.'::text),
(403079,44787,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il a nié ... nerveux quand les ailes arrivaient sur lui, évidemment.'::text,'s''être senti'::text,'se sentir'::text,'s''est senti'::text,'Il a nié s''être senti nerveux quand les ailes arrivaient sur lui, évidemment.'::text),
(403082,44787,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanatlar üstüne gelirken gergin ... inkâr etti, tabii ki.'::text,'hissettiğini'::text,'hissetmeyi'::text,'hissetti'::text,'Kanatlar üstüne gelirken gergin hissettiğini inkâr etti, tabii ki.'::text),
(403083,44787,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tagadta, hogy idegesnek ..., amikor a szárnyak felé közeledtek, nyilván.'::text,'érezte magát'::text,'érezni magát'::text,'érezte magát'::text,'Tagadta, hogy idegesnek érezte magát, amikor a szárnyak felé közeledtek, nyilván.'::text),
(403086,44788,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, er ... sich ducken sollen, die Flügel kamen so tief rein, echt.'::text,'hätte'::text,'musste nicht'::text,'konnte nicht'::text,'Bro, er hätte sich ducken sollen, die Flügel kamen so tief rein, echt.'::text),
(403090,44788,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, він ... пригнутися, ті крила летіли так низько, чесно.'::text,'мав би'::text,'не мусив'::text,'не міг'::text,'Бро, він мав би пригнутися, ті крила летіли так низько, чесно.'::text),
(403089,44788,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, ... agachado, esas alas venían tan bajas, en serio.'::text,'debería haberse'::text,'no tenía que haberse'::text,'no pudo haberse'::text,'Bro, debería haberse agachado, esas alas venían tan bajas, en serio.'::text),
(403088,44788,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frérot, il ... se baisser, ces ailes arrivaient trop bas, sérieux.'::text,'aurait dû'::text,'n''a pas dû'::text,'ne pouvait pas'::text,'Frérot, il aurait dû se baisser, ces ailes arrivaient trop bas, sérieux.'::text),
(403091,44788,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, eğilmesi ..., o kanatlar çok alçaktan geldi, cidden.'::text,'gerekirdi'::text,'gerekmezdi'::text,'mümkün değildi'::text,'Kanka, eğilmesi gerekirdi, o kanatlar çok alçaktan geldi, cidden.'::text),
(403092,44788,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, ... volna lehajolnia, azok a szárnyak nagyon alacsonyan jöttek, komolyan.'::text,'kellett'::text,'nem kellett'::text,'nem tudott'::text,'Tesó, kellett volna lehajolnia, azok a szárnyak nagyon alacsonyan jöttek, komolyan.'::text),
(403095,44789,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, er hat den Falken seine Flügel direkt auf seinem Handschuh ... lassen, einfach goated.'::text,'öffnen'::text,'öffnen'::text,'geöffnet'::text,'Yo, er hat den Falken seine Flügel direkt auf seinem Handschuh öffnen lassen, einfach goated.'::text),
(403099,44789,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Йо, він змусив сокола ... крила просто на його рукавиці, легенда.'::text,'розкрити'::text,'розкрити'::text,'розкрив'::text,'Йо, він змусив сокола розкрити крила просто на його рукавиці, легенда.'::text),
(403098,44789,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, hizo que el halcón ... las alas justo sobre su guante, un crack total.'::text,'abriera'::text,'abriera'::text,'abrió'::text,'Oye, hizo que el halcón abriera las alas justo sobre su guante, un crack total.'::text),
(403097,44789,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, il a fait ... ses ailes au faucon pile sur son gant, le GOAT.'::text,'ouvrir'::text,'ouvrir'::text,'ouvert'::text,'Yo, il a fait ouvrir ses ailes au faucon pile sur son gant, le GOAT.'::text),
(403100,44789,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, şahine kanatlarını tam eldiveninin üstünde ..., efsane valla.'::text,'açtırdı'::text,'açtırdı'::text,'açtı'::text,'Yo, şahine kanatlarını tam eldiveninin üstünde açtırdı, efsane valla.'::text),
(403101,44789,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyu, pont a kesztyűjén ... ki a sólyommal a szárnyait, kész legenda.'::text,'nyittatta'::text,'nyittatta'::text,'nyitotta'::text,'Figyu, pont a kesztyűjén nyittatta ki a sólyommal a szárnyait, kész legenda.'::text),
(403104,44790,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ich wünschte, unser Budget für 2026 ... so breit wie diese Flügel.'::text,'wäre'::text,'ist'::text,'wird sein'::text,'Ich wünschte, unser Budget für 2026 wäre so breit wie diese Flügel.'::text),
(403108,44790,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Хотів би я, щоб наш бюджет на 2026 рік ... таким широким, як ці крила.'::text,'був'::text,'є'::text,'буде'::text,'Хотів би я, щоб наш бюджет на 2026 рік був таким широким, як ці крила.'::text),
(403107,44790,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ojalá nuestro presupuesto de 2026 ... tan amplio como esas alas.'::text,'fuera'::text,'es'::text,'será'::text,'Ojalá nuestro presupuesto de 2026 fuera tan amplio como esas alas.'::text),
(403106,44790,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si seulement notre budget 2026 ... aussi large que ces ailes.'::text,'était'::text,'est'::text,'sera'::text,'Si seulement notre budget 2026 était aussi large que ces ailes.'::text),
(403109,44790,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Keşke 2026 bütçemiz o kanatlar kadar geniş ...'::text,'olsa'::text,NULL::text,'olacak'::text,'Keşke 2026 bütçemiz o kanatlar kadar geniş olsa.'::text),
(403110,44790,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bárcsak a 2026-os költségvetésünk olyan széles ..., mint azok a szárnyak.'::text,'lenne'::text,NULL::text,'lesz'::text,'Bárcsak a 2026-os költségvetésünk olyan széles lenne, mint azok a szárnyak.'::text),
(403113,44791,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Falke, ... Flügel weit geöffnet waren, landete auf seinem Handschuh.'::text,'dessen'::text,'der'::text,'welcher'::text,'Der Falke, dessen Flügel weit geöffnet waren, landete auf seinem Handschuh.'::text),
(403117,44791,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Сокіл, ... крила були широко розкриті, сів на його рукавицю.'::text,'чиї'::text,'який'::text,'котрий'::text,'Сокіл, чиї крила були широко розкриті, сів на його рукавицю.'::text),
(403116,44791,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El halcón, ... alas estaban bien abiertas, aterrizó en su guante.'::text,'cuyas'::text,'que'::text,'el cual'::text,'El halcón, cuyas alas estaban bien abiertas, aterrizó en su guante.'::text),
(403115,44791,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le faucon, ... les ailes étaient grandes ouvertes, s''est posé sur son gant.'::text,'dont'::text,'qui'::text,'que'::text,'Le faucon, dont les ailes étaient grandes ouvertes, s''est posé sur son gant.'::text),
(403118,44791,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Şahin, ... kanatları ardına kadar açıktı, eldivenine kondu.'::text,'ki onun'::text,'ki'::text,'ki'::text,'Şahin, ki onun kanatları ardına kadar açıktı, eldivenine kondu.'::text),
(403119,44791,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A sólyom, ... szárnyai szélesre tárva voltak, a kesztyűjére szállt.'::text,'amelynek a'::text,'amely'::text,'ami'::text,'A sólyom, amelynek a szárnyai szélesre tárva voltak, a kesztyűjére szállt.'::text),
(403122,44792,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'..., breitete der Falke seine Flügel auf seinem erhobenen Handschuh aus.'::text,'In der Dämmerung'::text,'In der Dämmerung'::text,'In einer Dämmerung'::text,'In der Dämmerung, breitete der Falke seine Flügel auf seinem erhobenen Handschuh aus.'::text),
(403126,44792,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'..., сокіл розправив крила на його піднятій рукавиці.'::text,'У сутінках'::text,'У сутінках'::text,'У сутінках'::text,'У сутінках, сокіл розправив крила на його піднятій рукавиці.'::text),
(403125,44792,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'..., el halcón desplegó las alas sobre su guante levantado.'::text,'Al anochecer'::text,'En el anochecer'::text,'En un anochecer'::text,'Al anochecer, el halcón desplegó las alas sobre su guante levantado.'::text),
(403124,44792,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'..., le faucon a déployé ses ailes sur son gant levé.'::text,'Au crépuscule'::text,'Au crépuscule'::text,'À un crépuscule'::text,'Au crépuscule, le faucon a déployé ses ailes sur son gant levé.'::text),
(403127,44792,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'..., şahin kanatlarını kaldırılmış eldivenin üstünde açtı.'::text,'Alacakaranlıkta'::text,'Alacakaranlıkta'::text,'Bir alacakaranlıkta'::text,'Alacakaranlıkta, şahin kanatlarını kaldırılmış eldivenin üstünde açtı.'::text),
(403128,44792,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'..., a sólyom kitárta a szárnyait a felemelt kesztyűjén.'::text,'Alkonyatkor'::text,'Az alkonyatkor'::text,'Egy alkonyatkor'::text,'Alkonyatkor, a sólyom kitárta a szárnyait a felemelt kesztyűjén.'::text),
(403131,44793,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... seiner breiten Flügel landete der Falke sanft auf seinem Handschuh.'::text,'Dank'::text,'Trotz'::text,'Obwohl'::text,'Dank seiner breiten Flügel landete der Falke sanft auf seinem Handschuh.'::text),
(403135,44793,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... своїм широким крилам сокіл м''яко сів на його рукавицю.'::text,'Завдяки'::text,'Попри'::text,'Хоча'::text,'Завдяки своїм широким крилам сокіл м''яко сів на його рукавицю.'::text),
(403134,44793,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... sus anchas alas, el halcón aterrizó suavemente en su guante.'::text,'Gracias a'::text,'A pesar de'::text,'Aunque'::text,'Gracias a sus anchas alas, el halcón aterrizó suavemente en su guante.'::text),
(403133,44793,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... ses larges ailes, le faucon s''est posé en douceur sur son gant.'::text,'Grâce à'::text,'Malgré'::text,'Bien que'::text,'Grâce à ses larges ailes, le faucon s''est posé en douceur sur son gant.'::text),
(403136,44793,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Geniş kanatları ..., şahin eldivenine yumuşakça kondu.'::text,'sayesinde'::text,'rağmen'::text,'olsa da'::text,'Geniş kanatları sayesinde, şahin eldivenine yumuşakça kondu.'::text),
(403137,44793,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Széles szárnyainak ... a sólyom puhán landolt a kesztyűjén.'::text,'köszönhetően'::text,'ellenére'::text,'bár'::text,'Széles szárnyainak köszönhetően a sólyom puhán landolt a kesztyűjén.'::text),
(350022,38892,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich gesagt, wenn ich diesen eleganten Morgenmantel hätte, ... ich ihn überall tragen, echt.'::text,'würde'::text,'werde'::text,'trug'::text,'Ehrlich gesagt, wenn ich diesen eleganten Morgenmantel hätte, würde ich ihn überall tragen, echt.'::text),
(350026,38892,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, якби в мене був той елегантний халат, я ... його всюди, реально.'::text,'носила б'::text,'носитиму'::text,'носила'::text,'Чесно, якби в мене був той елегантний халат, я носила б його всюди, реально.'::text),
(350025,38892,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'No voy a mentir, si tuviera esa bata elegante, la ... a todas partes, en serio.'::text,'llevaría'::text,'llevaré'::text,'llevé'::text,'No voy a mentir, si tuviera esa bata elegante, la llevaría a todas partes, en serio.'::text),
(350024,38892,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Je vais pas mentir, si j''avais ce peignoir élégant, je le ... partout, sérieux.'::text,'porterais'::text,'porterai'::text,'portais'::text,'Je vais pas mentir, si j''avais ce peignoir élégant, je le porterais partout, sérieux.'::text),
(350027,38892,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yalan yok, o şık sabahlık bende olsa her yerde ..., cidden.'::text,'giyerdim'::text,'giyeceğim'::text,'giydim'::text,'Yalan yok, o şık sabahlık bende olsa her yerde giyerdim, cidden.'::text),
(350028,38892,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nem hazudok, ha nekem lenne az az elegáns köntös, mindenhol ..., komolyan.'::text,'hordanám'::text,'hordani fogom'::text,'hordtam'::text,'Nem hazudok, ha nekem lenne az az elegáns köntös, mindenhol hordanám, komolyan.'::text),
(350031,38893,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Heute Morgen ... das elegante Parfüm zuerst auf ihr Handgelenk gesprüht.'::text,'wurde'::text,'wird'::text,'hat'::text,'Heute Morgen wurde das elegante Parfüm zuerst auf ihr Handgelenk gesprüht.'::text),
