(383823,42647,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az alany éppen a hetét ..., amikor megállt, hogy a jegyzetfüzetébe írjon, ahogy megfigyelték.'::text,'ütemezte'::text,'beütemezte'::text,'beütemezte'::text,'Az alany éppen a hetét ütemezte, amikor megállt, hogy a jegyzetfüzetébe írjon, ahogy megfigyelték.'::text),
(383826,42648,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Als du zurückgetreten bist, ... du den ganzen Monat verplant, ehrlich.'::text,'hattest'::text,'hast'::text,'hast'::text,'Als du zurückgetreten bist, hattest du den ganzen Monat verplant, ehrlich.'::text),
(383830,42648,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коли ти відступила назад, ти вже ... весь місяць, чесно.'::text,'розпланувала'::text,'розпланувала'::text,'розпланувала'::text,'Коли ти відступила назад, ти вже розпланувала весь місяць, чесно.'::text),
(383829,42648,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para cuando diste un paso atrás, ... todo el mes, la verdad.'::text,'habías programado'::text,'has programado'::text,'programaste'::text,'Para cuando diste un paso atrás, habías programado todo el mes, la verdad.'::text),
(383828,42648,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Quand tu as reculé, tu ... tout le mois, franchement.'::text,'avais planifié'::text,'as planifié'::text,'as planifié'::text,'Quand tu as reculé, tu avais planifié tout le mois, franchement.'::text),
(383831,42648,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Geri çekildiğinde bütün ayı çoktan ..., açıkçası.'::text,'planlamıştın'::text,'planladın'::text,'planladın'::text,'Geri çekildiğinde bütün ayı çoktan planlamıştın, açıkçası.'::text),
(383832,42648,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mire hátraléptél, már ... az egész hónapot, őszintén.'::text,'beütemezted'::text,'beütemezted'::text,'beütemezted'::text,'Mire hátraléptél, már beütemezted az egész hónapot, őszintén.'::text),
(383835,42649,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn sie noch ein Meeting plant, ... der Kalender keinen Platz mehr.'::text,'hat'::text,'hätte'::text,'hatte'::text,'Wenn sie noch ein Meeting plant, hat der Kalender keinen Platz mehr.'::text),
(383839,42649,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо вона запланує ще одну зустріч, у календарі ... вільного місця.'::text,'не залишиться'::text,'не залишилося б'::text,'не залишилося'::text,'Якщо вона запланує ще одну зустріч, у календарі не залишиться вільного місця.'::text),
(383838,42649,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si programa una reunión más, el calendario no ... espacio libre.'::text,'tendrá'::text,'tendría'::text,'tenía'::text,'Si programa una reunión más, el calendario no tendrá espacio libre.'::text),
(383837,42649,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si elle planifie une réunion de plus, le calendrier ... plus de place.'::text,'n''aura'::text,'n''aurait'::text,'n''avait'::text,'Si elle planifie une réunion de plus, le calendrier n''aura plus de place.'::text),
(383840,42649,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bir toplantı daha planlarsa takvimde hiç yer ...'::text,'kalmayacak'::text,'kalmazdı'::text,'kalmadı'::text,'Bir toplantı daha planlarsa takvimde hiç yer kalmayacak.'::text),
(383841,42649,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha még egy megbeszélést beütemez, a naptárban nem ... több hely.'::text,'marad'::text,'maradna'::text,'maradt'::text,'Ha még egy megbeszélést beütemez, a naptárban nem marad több hely.'::text),
(383853,42651,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Jedes Meeting ... auf einem rosa, orangefarbenen, grünen oder blauen Zettel eingeplant.'::text,'wird'::text,'plant'::text,'planend'::text,'Jedes Meeting wird auf einem rosa, orangefarbenen, grünen oder blauen Zettel eingeplant.'::text),
(383857,42651,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Кожну зустріч ... на рожевому, помаранчевому, зеленому чи синьому стікері.'::text,'заплановано'::text,'планує'::text,'плануючи'::text,'Кожну зустріч заплановано на рожевому, помаранчевому, зеленому чи синьому стікері.'::text),
(383856,42651,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cada reunión ... en una nota rosa, naranja, verde o azul.'::text,'está programada'::text,'programa'::text,'programando'::text,'Cada reunión está programada en una nota rosa, naranja, verde o azul.'::text),
(383855,42651,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Chaque réunion ... sur un post-it rose, orange, vert ou bleu.'::text,'est planifiée'::text,'planifie'::text,'planifiant'::text,'Chaque réunion est planifiée sur un post-it rose, orange, vert ou bleu.'::text),
(383858,42651,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Her toplantı pembe, turuncu, yeşil ya da mavi bir notta ...'::text,'planlanıyor'::text,'planlıyor'::text,'planlayarak'::text,'Her toplantı pembe, turuncu, yeşil ya da mavi bir notta planlanıyor.'::text),
(383859,42651,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Minden megbeszélés egy rózsaszín, narancs, zöld vagy kék cetlin ...'::text,'van beütemezve'::text,'ütemez'::text,'ütemezve'::text,'Minden megbeszélés egy rózsaszín, narancs, zöld vagy kék cetlin van beütemezve.'::text),
(383862,42652,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Stell dir vor: Sie ... den Monat des ganzen Teams allein, angeblich.'::text,'plante'::text,'wurde geplant'::text,'planend'::text,'Stell dir vor: Sie plante den Monat des ganzen Teams allein, angeblich.'::text),
(383866,42652,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Уяви: вона ... місяць для всієї команди сама, кажуть.'::text,'розпланувала'::text,'була запланована'::text,'плануючи'::text,'Уяви: вона розпланувала місяць для всієї команди сама, кажуть.'::text),
(383865,42652,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Fíjate: ... el mes de todo el equipo ella sola, al parecer.'::text,'programó'::text,'fue programada'::text,'programando'::text,'Fíjate: programó el mes de todo el equipo ella sola, al parecer.'::text),
(383864,42652,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute ça : elle ... le mois de toute l''équipe toute seule, apparemment.'::text,'a planifié'::text,'a été planifiée'::text,'planifiant'::text,'Écoute ça : elle a planifié le mois de toute l''équipe toute seule, apparemment.'::text),
(383867,42652,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Şuna bak: güya bütün ekibin ayını tek başına ...'::text,'planlamış'::text,'planlanmış'::text,'planlayarak'::text,'Şuna bak: güya bütün ekibin ayını tek başına planlamış.'::text),
(383868,42652,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Képzeld: állítólag egyedül ... az egész csapat hónapját.'::text,'ütemezte be'::text,'lett beütemezve'::text,'beütemezve'::text,'Képzeld: állítólag egyedül ütemezte be az egész csapat hónapját.'::text),
(383871,42653,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hör mal, ich hab gehört, sie ... diesen Monat frei sein; jedes Kästchen ist voll.'::text,'kann unmöglich'::text,'muss'::text,'könnte'::text,'Hör mal, ich hab gehört, sie kann unmöglich diesen Monat frei sein; jedes Kästchen ist voll.'::text),
(383875,42653,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, я чула, що цього місяця вона ... бути вільною; кожна клітинка заповнена.'::text,'не може'::text,'мусить'::text,'може'::text,'Слухай, я чула, що цього місяця вона не може бути вільною; кожна клітинка заповнена.'::text),
(383874,42653,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, me han dicho que este mes ... estar libre; cada casilla está llena.'::text,'no puede'::text,'debe de'::text,'podría'::text,'Oye, me han dicho que este mes no puede estar libre; cada casilla está llena.'::text),
(383873,42653,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute, j''ai entendu qu''elle ... être libre ce mois-ci ; chaque case est pleine.'::text,'ne peut pas'::text,'doit'::text,'pourrait'::text,'Écoute, j''ai entendu qu''elle ne peut pas être libre ce mois-ci ; chaque case est pleine.'::text),
(383876,42653,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, duydum ki bu ay boş ...; her kare dolu.'::text,'olamazmış'::text,'olmalıymış'::text,'olabilirmiş'::text,'Dinle, duydum ki bu ay boş olamazmış; her kare dolu.'::text),
(383877,42653,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, azt hallottam, hogy ebben a hónapban ... szabad; minden négyzet tele van.'::text,'nem lehet'::text,'biztosan'::text,'lehet'::text,'Figyelj, azt hallottam, hogy ebben a hónapban nem lehet szabad; minden négyzet tele van.'::text),
(383880,42654,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, der Monat, ... sie verplant hat, ist lowkey voll, kein freier Tag.'::text,'den'::text,'wer'::text,'wo'::text,'Bro, der Monat, den sie verplant hat, ist lowkey voll, kein freier Tag.'::text),
(383884,42654,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, місяць, ... вона розпланувала, трохи забитий, жодного вільного дня.'::text,'який'::text,'хто'::text,'де'::text,'Бро, місяць, який вона розпланувала, трохи забитий, жодного вільного дня.'::text),
(383883,42654,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, el mes ... programó está medio lleno, ni un día libre.'::text,'que'::text,'quien'::text,'donde'::text,'Bro, el mes que programó está medio lleno, ni un día libre.'::text),
(383882,42654,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frérot, le mois ... a planifié est un peu blindé, pas un seul jour de libre.'::text,'qu''elle'::text,'qui'::text,'où elle'::text,'Frérot, le mois qu''elle a planifié est un peu blindé, pas un seul jour de libre.'::text),
(383885,42654,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, onun ... ay hafiften full, tek bir boş gün yok.'::text,'planladığı'::text,'planlayan'::text,'planladığı yerde'::text,'Kanka, onun planladığı ay hafiften full, tek bir boş gün yok.'::text),
(383886,42654,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, a hónap, ... beütemezett, eléggé tele van, egy szabad nap sincs.'::text,'amit'::text,'aki'::text,'ahol'::text,'Tesó, a hónap, amit beütemezett, eléggé tele van, egy szabad nap sincs.'::text),
(383889,42655,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, sie meinte, sie ... auch meinen Geburtstag einplanen, lowkey ikonisch.'::text,'würde'::text,'wird'::text,'plant'::text,'Bro, sie meinte, sie würde auch meinen Geburtstag einplanen, lowkey ikonisch.'::text),
(383893,42655,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, вона сказала, що ... і мій день народження, трохи культово.'::text,'запланує'::text,'запланує'::text,'планує'::text,'Бро, вона сказала, що запланує і мій день народження, трохи культово.'::text),
(383892,42655,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, dijo que ... también mi cumpleaños, medio icónico.'::text,'programaría'::text,'programará'::text,'programa'::text,'Bro, dijo que programaría también mi cumpleaños, medio icónico.'::text),
(383891,42655,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frérot, elle a dit qu''elle ... aussi mon anniversaire, un peu iconique.'::text,'planifierait'::text,'planifiera'::text,'planifie'::text,'Frérot, elle a dit qu''elle planifierait aussi mon anniversaire, un peu iconique.'::text),
(383894,42655,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, benim doğum günümü de ... söyledi, hafiften efsane.'::text,'planlayacağını'::text,'planlayacağını'::text,'planladığını'::text,'Kanka, benim doğum günümü de planlayacağını söyledi, hafiften efsane.'::text),
(383895,42655,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, azt mondta, hogy a szülinapomat is ..., eléggé ikonikus.'::text,'beütemezi'::text,'beütemezi'::text,'beütemezi'::text,'Tesó, azt mondta, hogy a szülinapomat is beütemezi, eléggé ikonikus.'::text),
(354252,39362,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... den Kolben mit der blauen Flüssigkeit seit fünf Minuten.'::text,'schwenkt'::text,'schwenkt'::text,'schwenkt'::text,'Sie schwenkt den Kolben mit der blauen Flüssigkeit seit fünf Minuten.'::text),
(354256,39362,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона ... колбу з синьою рідиною вже п''ять хвилин.'::text,'крутить'::text,'крутить'::text,'крутить'::text,'Вона крутить колбу з синьою рідиною вже п''ять хвилин.'::text),
(354255,39362,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hace cinco minutos que ... el matraz de líquido azul.'::text,'agita'::text,'está agitando'::text,'agita'::text,'Hace cinco minutos que agita el matraz de líquido azul.'::text),
(354254,39362,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle ... la fiole de liquide bleu depuis cinq minutes.'::text,'fait tourner'::text,'fait tourner'::text,'fait tourner'::text,'Elle fait tourner la fiole de liquide bleu depuis cinq minutes.'::text),
(354257,39362,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Beş dakikadır mavi sıvılı cam balonu ...'::text,'çalkalıyor'::text,'çalkalıyor'::text,'çalkalar'::text,'Beş dakikadır mavi sıvılı cam balonu çalkalıyor.'::text),
(354258,39362,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Öt perce ... a kék folyadékos lombikot.'::text,'forgatja'::text,'forgatja'::text,'forgatja'::text,'Öt perce forgatja a kék folyadékos lombikot.'::text),
(354261,39363,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... den Kolben gegen das Licht, als ihr Kollege herübersah.'::text,'hielt'::text,'hielt'::text,'hat gehalten'::text,'Sie hielt den Kolben gegen das Licht, als ihr Kollege herübersah.'::text),
(354265,39363,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона ... колбу проти світла, коли колега глянув у її бік.'::text,'тримала'::text,'підняла'::text,'підняла'::text,'Вона тримала колбу проти світла, коли колега глянув у її бік.'::text),
(354264,39363,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cuando su compañero miró hacia ella, ... el matraz a contraluz.'::text,'sostenía'::text,'sostuvo'::text,'ha sostenido'::text,'Cuando su compañero miró hacia ella, sostenía el matraz a contraluz.'::text),
(354263,39363,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle ... la fiole à la lumière quand son collègue a regardé.'::text,'tenait'::text,'a tenu'::text,'a tenu'::text,'Elle tenait la fiole à la lumière quand son collègue a regardé.'::text),
(354266,39363,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Meslektaşı ona baktığında cam balonu ışığa doğru ...'::text,'tutuyordu'::text,'tuttu'::text,'tuttu'::text,'Meslektaşı ona baktığında cam balonu ışığa doğru tutuyordu.'::text),
(354267,39363,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Éppen a fény felé ... a lombikot, amikor a kollégája odanézett.'::text,'tartotta'::text,'tartotta'::text,'tartotta'::text,'Éppen a fény felé tartotta a lombikot, amikor a kollégája odanézett.'::text),
(354270,39364,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ihr Kollege schlug vor, den rosa Kolben unter das Mikroskop zu ...'::text,'legen'::text,'legen'::text,'legen'::text,'Ihr Kollege schlug vor, den rosa Kolben unter das Mikroskop zu legen.'::text),
(354274,39364,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Її колега запропонував ... рожеву колбу під мікроскоп.'::text,'покласти'::text,'покласти'::text,'покласти'::text,'Її колега запропонував покласти рожеву колбу під мікроскоп.'::text),
(354273,39364,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Su compañero sugirió ... el matraz rosa bajo el microscopio.'::text,'poner'::text,'poner'::text,'poner'::text,'Su compañero sugirió poner el matraz rosa bajo el microscopio.'::text),
(354272,39364,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Son collègue a suggéré de ... la fiole rose sous le microscope.'::text,'mettre'::text,'mettre'::text,'mettre'::text,'Son collègue a suggéré de mettre la fiole rose sous le microscope.'::text),
(354275,39364,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Meslektaşı pembe cam balonu mikroskobun altına ... önerdi.'::text,'koymayı'::text,'koymayı'::text,'koymayı'::text,'Meslektaşı pembe cam balonu mikroskobun altına koymayı önerdi.'::text),
(354276,39364,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A kollégája azt javasolta, hogy ... a rózsaszín lombikot a mikroszkóp alá.'::text,'tegye'::text,'tegye'::text,'tegye'::text,'A kollégája azt javasolta, hogy tegye a rózsaszín lombikot a mikroszkóp alá.'::text),
(354279,39365,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, sie ... Handschuhe anziehen sollen, bevor sie den heißen Kolben angefasst hat, echt.'::text,'hätte'::text,'musste'::text,'konnte nicht'::text,'Bro, sie hätte Handschuhe anziehen sollen, bevor sie den heißen Kolben angefasst hat, echt.'::text),
(354283,39365,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, вона ... вдягти рукавички, перш ніж торкатися тієї гарячої колби, реально.'::text,'мала б'::text,'мабуть, мала'::text,'не могла'::text,'Бро, вона мала б вдягти рукавички, перш ніж торкатися тієї гарячої колби, реально.'::text),
(354282,39365,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, ... puesto guantes antes de tocar ese matraz caliente, en serio.'::text,'debería haberse'::text,'debe de haberse'::text,'no puede haberse'::text,'Bro, debería haberse puesto guantes antes de tocar ese matraz caliente, en serio.'::text),
(354281,39365,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frérot, elle ... mettre des gants avant de toucher cette fiole brûlante, sérieux.'::text,'aurait dû'::text,'a dû'::text,'n''a pas pu'::text,'Frérot, elle aurait dû mettre des gants avant de toucher cette fiole brûlante, sérieux.'::text),
(354284,39365,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, o sıcak cam balona dokunmadan önce eldiven ..., cidden.'::text,'giymeliydi'::text,'giymiş olmalı'::text,'giymiş olamaz'::text,'Kanka, o sıcak cam balona dokunmadan önce eldiven giymeliydi, cidden.'::text),
(354285,39365,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, ... kesztyűt, mielőtt megfogta azt a forró lombikot, komolyan.'::text,'fel kellett volna vennie'::text,'biztos felvett'::text,'nem vehetett fel'::text,'Tesó, fel kellett volna vennie kesztyűt, mielőtt megfogta azt a forró lombikot, komolyan.'::text),
(354297,39367,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ihr Kollege wünschte, er ... auch einen Kolben mit leuchtend rosa Flüssigkeit.'::text,'hätte'::text,'hat'::text,'würde haben'::text,'Ihr Kollege wünschte, er hätte auch einen Kolben mit leuchtend rosa Flüssigkeit.'::text),
(354301,39367,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Її колега хотів би, щоб і в нього ... колба зі світною рожевою рідиною.'::text,'була'::text,'є'::text,'була б'::text,'Її колега хотів би, щоб і в нього була колба зі світною рожевою рідиною.'::text),
(354300,39367,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Su compañero desearía ... también un matraz de líquido rosa luminoso.'::text,'tener'::text,'tiene'::text,'tendría'::text,'Su compañero desearía tener también un matraz de líquido rosa luminoso.'::text),
(354299,39367,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Son collègue aimerait ... lui aussi une fiole de liquide rose lumineux.'::text,'avoir'::text,'a'::text,'aurait'::text,'Son collègue aimerait avoir lui aussi une fiole de liquide rose lumineux.'::text),
(354302,39367,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Meslektaşı keşke onun da parlayan pembe sıvılı bir cam balonu ... diye düşünüyor.'::text,'olsa'::text,'var'::text,'olurdu'::text,'Meslektaşı keşke onun da parlayan pembe sıvılı bir cam balonu olsa diye düşünüyor.'::text),
(354303,39367,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A kollégája azt kívánja, bárcsak neki is ... egy lombikja világító rózsaszín folyadékkal.'::text,'lenne'::text,'van'::text,'lenne'::text,'A kollégája azt kívánja, bárcsak neki is lenne egy lombikja világító rózsaszín folyadékkal.'::text),
(354306,39368,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Kolben, ... Inhalt allmählich die Farbe wechselt, wird unter starkem Licht beobachtet.'::text,'dessen'::text,'der'::text,'welcher'::text,'Der Kolben, dessen Inhalt allmählich die Farbe wechselt, wird unter starkem Licht beobachtet.'::text),
(354310,39368,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Колба, ... вміст поступово змінює колір, спостерігається під сильним світлом.'::text,'чий'::text,'яка'::text,'котра'::text,'Колба, чий вміст поступово змінює колір, спостерігається під сильним світлом.'::text),
(354309,39368,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El matraz, ... contenido cambia de color gradualmente, se observa bajo una luz intensa.'::text,'cuyo'::text,'que'::text,'el cual'::text,'El matraz, cuyo contenido cambia de color gradualmente, se observa bajo una luz intensa.'::text),
(354308,39368,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La fiole, ... le contenu change progressivement de couleur, est observée sous une forte lumière.'::text,'dont'::text,'qui'::text,'que'::text,'La fiole, dont le contenu change progressivement de couleur, est observée sous une forte lumière.'::text),
(354311,39368,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cam balon, ... içeriği giderek renk değiştirir, güçlü ışık altında gözlemlenir.'::text,'ki onun'::text,'ki'::text,'ki'::text,'Cam balon, ki onun içeriği giderek renk değiştirir, güçlü ışık altında gözlemlenir.'::text),
(354312,39368,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A lombikot, ... tartalma fokozatosan színt vált, erős fényben figyelik meg.'::text,'amelynek a'::text,'amely'::text,'ami'::text,'A lombikot, amelynek a tartalma fokozatosan színt vált, erős fényben figyelik meg.'::text),
(354315,39369,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie hält den rosa Kolben hoch, als wäre er ... Entdeckung der Geschichte, und alle müssen ihn sehen!'::text,'die größte'::text,'eine größte'::text,'größte'::text,'Sie hält den rosa Kolben hoch, als wäre er die größte Entdeckung der Geschichte, und alle müssen ihn sehen!'::text),
(354319,39369,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона тримає рожеву колбу так, ніби це ... відкриття в історії, і всі мусять її побачити!'::text,'найбільше'::text,'найбільше'::text,'найбільше'::text,'Вона тримає рожеву колбу так, ніби це найбільше відкриття в історії, і всі мусять її побачити!'::text),
(354318,39369,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Levanta el matraz rosa como si fuera ... descubrimiento de la historia, y todos deben verlo!'::text,'el mayor'::text,'un mayor'::text,'mayor'::text,'¡Levanta el matraz rosa como si fuera el mayor descubrimiento de la historia, y todos deben verlo!'::text),
(354317,39369,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle brandit la fiole rose comme si c''était ... découverte de l''histoire, et tout le monde doit la voir !'::text,'la plus grande'::text,'une plus grande'::text,'plus grande'::text,'Elle brandit la fiole rose comme si c''était la plus grande découverte de l''histoire, et tout le monde doit la voir !'::text),
(354320,39369,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Pembe cam balonu tarihin ... keşfiymiş gibi havaya kaldırıyor ve herkes onu görmeli!'::text,'en büyük'::text,'bir en büyük'::text,'en büyük'::text,'Pembe cam balonu tarihin en büyük keşfiymiş gibi havaya kaldırıyor ve herkes onu görmeli!'::text),
(354321,39369,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Úgy tartja fel a rózsaszín lombikot, mintha ez lenne ... felfedezés a történelemben, és mindenkinek látnia kell!'::text,'a legnagyobb'::text,'egy legnagyobb'::text,'legnagyobb'::text,'Úgy tartja fel a rózsaszín lombikot, mintha ez lenne a legnagyobb felfedezés a történelemben, és mindenkinek látnia kell!'::text),
(354324,39370,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... all ihrer Vorsicht könnte der Kolben auf der Heizplatte jeden Moment zerspringen!'::text,'Trotz'::text,'Aufgrund'::text,'Vorausgesetzt'::text,'Trotz all ihrer Vorsicht könnte der Kolben auf der Heizplatte jeden Moment zerspringen!'::text),
(354328,39370,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... всю її обережність колба може будь-якої миті розбитися на тій плитці!'::text,'Попри'::text,'Через'::text,'За умови'::text,'Попри всю її обережність колба може будь-якої миті розбитися на тій плитці!'::text),
(354327,39370,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡... todo su cuidado, el matraz podría estallar en esa placa en cualquier momento!'::text,'A pesar de'::text,'Debido a'::text,'Siempre que'::text,'¡A pesar de todo su cuidado, el matraz podría estallar en esa placa en cualquier momento!'::text),
(354326,39370,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... toutes ses précautions, la fiole pourrait éclater sur cette plaque à tout moment !'::text,'Malgré'::text,'En raison de'::text,'Pourvu que'::text,'Malgré toutes ses précautions, la fiole pourrait éclater sur cette plaque à tout moment !'::text),
(354329,39370,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Onca dikkatine ..., cam balon o ocakta her an parçalanabilir!'::text,'rağmen'::text,'yüzünden'::text,'şartıyla'::text,'Onca dikkatine rağmen, cam balon o ocakta her an parçalanabilir!'::text),
(354330,39370,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Minden óvatossága ... a lombik bármelyik pillanatban szétrobbanhat azon a főzőlapon!'::text,'ellenére'::text,'miatt'::text,'feltéve'::text,'Minden óvatossága ellenére a lombik bármelyik pillanatban szétrobbanhat azon a főzőlapon!'::text),
(354333,39371,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis Mitternacht wird sie jeden einzelnen Kolben in diesem Labor ..., sonst ist alles ruiniert!'::text,'getestet haben'::text,'testen'::text,'testen'::text,'Bis Mitternacht wird sie jeden einzelnen Kolben in diesem Labor getestet haben, sonst ist alles ruiniert!'::text),
(354337,39371,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До півночі вона ... кожну колбу в цій лабораторії, інакше все зруйновано!'::text,'перевірить'::text,'перевірятиме'::text,'перевіряє'::text,'До півночі вона перевірить кожну колбу в цій лабораторії, інакше все зруйновано!'::text),
(354336,39371,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Para medianoche, ... cada uno de los matraces de este laboratorio, o todo está arruinado!'::text,'habrá probado'::text,'probará'::text,'prueba'::text,'¡Para medianoche, habrá probado cada uno de los matraces de este laboratorio, o todo está arruinado!'::text),
(354335,39371,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''ici minuit, elle ... chaque fiole de ce labo, sinon tout est fichu !'::text,'aura testé'::text,'testera'::text,'teste'::text,'D''ici minuit, elle aura testé chaque fiole de ce labo, sinon tout est fichu !'::text),
(354338,39371,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gece yarısına kadar bu laboratuvardaki her bir cam balonu ..., yoksa her şey mahvolur!'::text,'test etmiş olacak'::text,'test edecek'::text,'test ediyor'::text,'Gece yarısına kadar bu laboratuvardaki her bir cam balonu test etmiş olacak, yoksa her şey mahvolur!'::text),
(354339,39371,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Éjfélig ... ennek a laboratóriumnak minden egyes lombikját, különben minden odavan!'::text,'leteszteli'::text,'tesztelni fogja'::text,'teszteli'::text,'Éjfélig leteszteli ennek a laboratóriumnak minden egyes lombikját, különben minden odavan!'::text),
(355647,39517,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der junge Mann ... seit zehn Minuten die schlammigen Fußabdrücke von den Fliesen.'::text,'wischt'::text,'hat gewischt'::text,'wischt'::text,'Der junge Mann wischt seit zehn Minuten die schlammigen Fußabdrücke von den Fliesen.'::text),
(355651,39517,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Молодий чоловік ... брудні сліди з плитки вже десять хвилин.'::text,'змиває'::text,'змив'::text,'змиває'::text,'Молодий чоловік змиває брудні сліди з плитки вже десять хвилин.'::text),
(355650,39517,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El joven ... las huellas de barro de las baldosas desde hace diez minutos.'::text,'friega'::text,'ha fregado'::text,'friega'::text,'El joven friega las huellas de barro de las baldosas desde hace diez minutos.'::text),
(355649,39517,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le jeune homme ... les traces de pas boueuses sur le carrelage depuis dix minutes.'::text,'nettoie'::text,'a nettoyé'::text,'nettoie'::text,'Le jeune homme nettoie les traces de pas boueuses sur le carrelage depuis dix minutes.'::text),
(355652,39517,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Genç adam on dakikadır çamurlu ayak izlerini fayanslardan ...'::text,'siliyor'::text,'sildi'::text,'siler'::text,'Genç adam on dakikadır çamurlu ayak izlerini fayanslardan siliyor.'::text),
(355653,39517,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A fiatalember tíz perce ... a sáros lábnyomokat a csempékről.'::text,'mossa fel'::text,'felmosta'::text,'felmossa'::text,'A fiatalember tíz perce mossa fel a sáros lábnyomokat a csempékről.'::text),
(355656,39518,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Als die Großmutter den Flur sah, hatten die schlammigen Fußabdrücke schon alle Fliesen ...'::text,'bedeckt'::text,'bedeckt'::text,'bedeckt'::text,'Als die Großmutter den Flur sah, hatten die schlammigen Fußabdrücke schon alle Fliesen bedeckt.'::text),
(355660,39518,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коли бабуся побачила коридор, брудні сліди вже ... всю плитку.'::text,'вкрили'::text,'вкрили'::text,'вкривають'::text,'Коли бабуся побачила коридор, брудні сліди вже вкрили всю плитку.'::text),
(355659,39518,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cuando la abuela vio el pasillo, las huellas de barro ya ... todas las baldosas.'::text,'habían cubierto'::text,'han cubierto'::text,'cubren'::text,'Cuando la abuela vio el pasillo, las huellas de barro ya habían cubierto todas las baldosas.'::text),
(355658,39518,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Quand la grand-mère a vu le couloir, les traces de pas boueuses ... tout le carrelage.'::text,'avaient couvert'::text,'ont couvert'::text,'couvrent'::text,'Quand la grand-mère a vu le couloir, les traces de pas boueuses avaient couvert tout le carrelage.'::text),
(355661,39518,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Büyükanne koridoru gördüğünde çamurlu ayak izleri bütün fayansları çoktan ...'::text,'kaplamıştı'::text,'kapladı'::text,'kaplıyor'::text,'Büyükanne koridoru gördüğünde çamurlu ayak izleri bütün fayansları çoktan kaplamıştı.'::text),
(355662,39518,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mire a nagymama meglátta a folyosót, a sáros lábnyomok már az összes csempét ...'::text,'beborították'::text,'beborították'::text,'borítják'::text,'Mire a nagymama meglátta a folyosót, a sáros lábnyomok már az összes csempét beborították.'::text),
(355665,39519,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn er die Fußabdrücke jetzt aufwischt, ... seine Großmutter nicht mehr wütend.'::text,'ist'::text,'wäre'::text,'war'::text,'Wenn er die Fußabdrücke jetzt aufwischt, ist seine Großmutter nicht mehr wütend.'::text),
(355669,39519,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо він зараз змиє сліди, бабуся більше ... сердитою.'::text,'не буде'::text,'не була б'::text,'не була'::text,'Якщо він зараз змиє сліди, бабуся більше не буде сердитою.'::text),
(355668,39519,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si friega las huellas ahora, su abuela ya no ... enfadada.'::text,'estará'::text,'estaría'::text,'estaba'::text,'Si friega las huellas ahora, su abuela ya no estará enfadada.'::text),
(355667,39519,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'S''il nettoie les traces de pas maintenant, sa grand-mère ... plus en colère.'::text,'ne sera'::text,'ne serait'::text,'n''était'::text,'S''il nettoie les traces de pas maintenant, sa grand-mère ne sera plus en colère.'::text),
(355670,39519,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ayak izlerini şimdi silerse büyükannesi artık kızgın ...'::text,'olmayacak'::text,'olmazdı'::text,'değildi'::text,'Ayak izlerini şimdi silerse büyükannesi artık kızgın olmayacak.'::text),
(355671,39519,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha most felmossa a lábnyomokat, a nagymamája már nem ... dühös.'::text,'lesz'::text,'lenne'::text,'volt'::text,'Ha most felmossa a lábnyomokat, a nagymamája már nem lesz dühös.'::text),
(355674,39520,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Zöge er seine Stiefel aus, ... das Reinigungsbudget für Fußabdrücke um 50 Prozent.'::text,'sänke'::text,'sinkt'::text,'sank'::text,'Zöge er seine Stiefel aus, sänke das Reinigungsbudget für Fußabdrücke um 50 Prozent.'::text),
(355678,39520,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби він зняв черевики, бюджет на прибирання слідів ... на 50 відсотків.'::text,'скоротився б'::text,'скоротиться'::text,'скоротився'::text,'Якби він зняв черевики, бюджет на прибирання слідів скоротився б на 50 відсотків.'::text),
(355677,39520,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si se quitara las botas, el presupuesto de limpieza de huellas ... un 50 por ciento.'::text,'bajaría'::text,'bajará'::text,'bajó'::text,'Si se quitara las botas, el presupuesto de limpieza de huellas bajaría un 50 por ciento.'::text),
(355676,39520,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'S''il enlevait ses bottes, le budget de nettoyage des traces de pas ... de 50 pour cent.'::text,'baisserait'::text,'baissera'::text,'a baissé'::text,'S''il enlevait ses bottes, le budget de nettoyage des traces de pas baisserait de 50 pour cent.'::text),
(355679,39520,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Botlarını çıkarsa ayak izleri için temizlik bütçesi yüzde 50 ...'::text,'düşerdi'::text,'düşecek'::text,'düştü'::text,'Botlarını çıkarsa ayak izleri için temizlik bütçesi yüzde 50 düşerdi.'::text),
(355680,39520,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha levenné a csizmáját, a lábnyomok takarítási költségvetése 50 százalékkal ...'::text,'csökkenne'::text,'csökken'::text,'csökkent'::text,'Ha levenné a csizmáját, a lábnyomok takarítási költségvetése 50 százalékkal csökkenne.'::text),
(355683,39521,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Fußabdrücke ... von schlammigen Stiefeln gemacht, deshalb haben sie die Form von Stiefeln.'::text,'wurden'::text,'haben'::text,'machen gerade'::text,'Die Fußabdrücke wurden von schlammigen Stiefeln gemacht, deshalb haben sie die Form von Stiefeln.'::text),
(355687,39521,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Сліди ... брудними черевиками, тому вони мають форму черевиків.'::text,'були залишені'::text,'залишили'::text,'залишають'::text,'Сліди були залишені брудними черевиками, тому вони мають форму черевиків.'::text),
(355686,39521,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Las huellas ... por botas embarradas, así que tienen forma de botas.'::text,'fueron hechas'::text,'hicieron'::text,'están haciendo'::text,'Las huellas fueron hechas por botas embarradas, así que tienen forma de botas.'::text),
(355685,39521,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les traces de pas ... par des bottes boueuses, donc elles ont la forme de bottes.'::text,'ont été faites'::text,'ont fait'::text,'font'::text,'Les traces de pas ont été faites par des bottes boueuses, donc elles ont la forme de bottes.'::text),
(355688,39521,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ayak izleri çamurlu botlarla ..., yani bot şeklindeler.'::text,'yapıldı'::text,'yaptı'::text,'yapıyor'::text,'Ayak izleri çamurlu botlarla yapıldı, yani bot şeklindeler.'::text),
(355689,39521,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A lábnyomokat sáros csizmák ..., ezért csizma alakúak.'::text,'hagyták'::text,'hagyták'::text,'hagyják'::text,'A lábnyomokat sáros csizmák hagyták, ezért csizma alakúak.'::text),
(355701,39523,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Diese riesigen schlammigen Fußabdrücke ... ihrem Enkel gehören, und sie ist absolut wütend!'::text,'müssen'::text,'können nicht'::text,'dürfen nicht'::text,'Diese riesigen schlammigen Fußabdrücke müssen ihrem Enkel gehören, und sie ist absolut wütend!'::text),
(355705,39523,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ці величезні брудні сліди ... належати її онукові, і вона просто в люті!'::text,'мусять'::text,'не можуть'::text,'не повинні'::text,'Ці величезні брудні сліди мусять належати її онукові, і вона просто в люті!'::text),
(355704,39523,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Estas enormes huellas de barro ... ser de su nieto, y ella está furiosísima!'::text,'deben de'::text,'no pueden'::text,'no deben'::text,'¡Estas enormes huellas de barro deben de ser de su nieto, y ella está furiosísima!'::text),
(355703,39523,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ces énormes traces de pas boueuses ... appartenir à son petit-fils, et elle est absolument furieuse !'::text,'doivent'::text,'ne peuvent pas'::text,'ne doivent pas'::text,'Ces énormes traces de pas boueuses doivent appartenir à son petit-fils, et elle est absolument furieuse !'::text),
(355706,39523,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu kocaman çamurlu ayak izleri torununa ait ... ve o resmen öfkeden deliriyor!'::text,'olmalı'::text,'olamaz'::text,'olmamalı'::text,'Bu kocaman çamurlu ayak izleri torununa ait olmalı ve o resmen öfkeden deliriyor!'::text),
(355707,39523,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ezek a hatalmas sáros lábnyomok ... az unokájáé, és ő teljesen dühöng!'::text,'biztosan'::text,'nem lehetnek'::text,'nem lehetnek'::text,'Ezek a hatalmas sáros lábnyomok biztosan az unokájáé, és ő teljesen dühöng!'::text),
(355710,39524,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der junge Mann, ... Fußabdrücke den weißen Flur ruiniert haben, steckt in riesigen Schwierigkeiten!'::text,'dessen'::text,'der'::text,'welcher'::text,'Der junge Mann, dessen Fußabdrücke den weißen Flur ruiniert haben, steckt in riesigen Schwierigkeiten!'::text),
(355714,39524,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Молодий чоловік, ... сліди зіпсували білий коридор, у страшній халепі!'::text,'чиї'::text,'який'::text,'котрий'::text,'Молодий чоловік, чиї сліди зіпсували білий коридор, у страшній халепі!'::text),
(355713,39524,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡El joven ... huellas arruinaron el pasillo blanco está en un lío tremendo!'::text,'cuyas'::text,'que'::text,'el cual'::text,'¡El joven cuyas huellas arruinaron el pasillo blanco está en un lío tremendo!'::text),
(355712,39524,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le jeune homme ... les traces de pas ont ruiné le couloir blanc est dans un pétrin terrible !'::text,'dont'::text,'qui'::text,'lequel'::text,'Le jeune homme dont les traces de pas ont ruiné le couloir blanc est dans un pétrin terrible !'::text),
(355715,39524,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Genç adam, ... ayak izleri beyaz koridoru mahvetti, başı fena halde belada!'::text,'ki onun'::text,'ki'::text,'ki'::text,'Genç adam, ki onun ayak izleri beyaz koridoru mahvetti, başı fena halde belada!'::text),
(355716,39524,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A fiatalember, ... lábnyomai tönkretették a fehér folyosót, szörnyű bajban van!'::text,'akinek a'::text,'aki'::text,'amely'::text,'A fiatalember, akinek a lábnyomai tönkretették a fehér folyosót, szörnyű bajban van!'::text),
(355719,39525,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nonna sagte, die Fußabdrücke ... die schlimmste Katastrophe, die ihr Flur je gesehen hatte!'::text,'seien'::text,'sind'::text,'seien gewesen'::text,'Nonna sagte, die Fußabdrücke seien die schlimmste Katastrophe, die ihr Flur je gesehen hatte!'::text),
(355723,39525,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Нонна сказала, що ці сліди ... найгіршою катастрофою, яку будь-коли бачив її коридор!'::text,'були'::text,'є'::text,'були'::text,'Нонна сказала, що ці сліди були найгіршою катастрофою, яку будь-коли бачив її коридор!'::text),
(355722,39525,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡La nonna dijo que las huellas ... el peor desastre que su pasillo había visto jamás!'::text,'eran'::text,'son'::text,'han sido'::text,'¡La nonna dijo que las huellas eran el peor desastre que su pasillo había visto jamás!'::text),
(355721,39525,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nonna a dit que les traces de pas ... la pire catastrophe que son couloir ait jamais vue !'::text,'étaient'::text,'sont'::text,'ont été'::text,'Nonna a dit que les traces de pas étaient la pire catastrophe que son couloir ait jamais vue !'::text),
(355724,39525,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nonna ayak izlerinin koridorunun gördüğü en büyük felaket ... söyledi!'::text,'olduğunu'::text,'olduğunu'::text,'olduğunu'::text,'Nonna ayak izlerinin koridorunun gördüğü en büyük felaket olduğunu söyledi!'::text),
(355725,39525,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nonna azt mondta, hogy a lábnyomok ... a legnagyobb katasztrófát, amit a folyosója valaha látott!'::text,'jelentették'::text,'jelentik'::text,'jelentették'::text,'Nonna azt mondta, hogy a lábnyomok jelentették a legnagyobb katasztrófát, amit a folyosója valaha látott!'::text),
(355728,39526,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mädel, angeblich ... er schon als Kind immer schlammige Fußabdrücke.'::text,'hinterließ'::text,'hinterließ'::text,'war gewohnt zu hinterlassen'::text,'Mädel, angeblich hinterließ er schon als Kind immer schlammige Fußabdrücke.'::text),
(355732,39526,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, кажуть, він і в дитинстві ... брудні сліди.'::text,'завжди залишав'::text,'завжди залишав'::text,'звик залишати'::text,'Подруго, кажуть, він і в дитинстві завжди залишав брудні сліди.'::text),
(355731,39526,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tía, parece que de niño también ... dejar siempre huellas de barro.'::text,'solía'::text,'solía'::text,'estaba acostumbrado a'::text,'Tía, parece que de niño también solía dejar siempre huellas de barro.'::text),
(355730,39526,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Meuf, apparemment, quand il était petit aussi, il ... toujours des traces de pas boueuses.'::text,'laissait'::text,'laissait'::text,'avait l''habitude de laisser'::text,'Meuf, apparemment, quand il était petit aussi, il laissait toujours des traces de pas boueuses.'::text),
(355733,39526,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, güya çocukken de hep çamurlu ayak izleri ...'::text,'bırakırdı'::text,'bırakırdı'::text,'bırakmaya alışkındı'::text,'Kızım, güya çocukken de hep çamurlu ayak izleri bırakırdı.'::text),
(355734,39526,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, állítólag gyerekként is mindig sáros lábnyomokat ...'::text,'hagyott'::text,'hagyott'::text,'szokott hagyni'::text,'Csajszi, állítólag gyerekként is mindig sáros lábnyomokat hagyott.'::text),
(355737,39527,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hör mal, sie hat mir erzählt, er hat versprochen, zuerst seine Stiefel ..., und dann sind die Fußabdrücke passiert.'::text,'abzuwischen'::text,'abzuwischen'::text,'abzuwischen'::text,'Hör mal, sie hat mir erzählt, er hat versprochen, zuerst seine Stiefel abzuwischen, und dann sind die Fußabdrücke passiert.'::text),
(355741,39527,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, вона сказала, що він пообіцяв спершу ... черевики, а потім сталися ці сліди.'::text,'витерти'::text,'витерти'::text,'витерти'::text,'Слухай, вона сказала, що він пообіцяв спершу витерти черевики, а потім сталися ці сліди.'::text),
(355740,39527,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, me dijo que prometió ... las botas primero, y luego pasaron las huellas.'::text,'limpiarse'::text,'limpiarse'::text,'limpiarse'::text,'Oye, me dijo que prometió limpiarse las botas primero, y luego pasaron las huellas.'::text),
(355739,39527,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute, elle m''a dit qu''il avait promis de ... ses bottes d''abord, et puis les traces de pas sont arrivées.'::text,'nettoyer'::text,'nettoyer'::text,'nettoyer'::text,'Écoute, elle m''a dit qu''il avait promis de nettoyer ses bottes d''abord, et puis les traces de pas sont arrivées.'::text),
(355742,39527,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, bana dediğine göre önce botlarını ... söz vermiş, sonra da o ayak izleri oldu.'::text,'silmeye'::text,'silmeye'::text,'silmeye'::text,'Dinle, bana dediğine göre önce botlarını silmeye söz vermiş, sonra da o ayak izleri oldu.'::text),
(355743,39527,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, azt mondta, hogy megígérte, hogy előbb ... a csizmáját, aztán jöttek a lábnyomok.'::text,'letörli'::text,'letörli'::text,'letörli'::text,'Figyelj, azt mondta, hogy megígérte, hogy előbb letörli a csizmáját, aztán jöttek a lábnyomok.'::text),
(398766,44308,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Während sie tropisches Obst in eine Tüte ..., blieb die Ananas, wo sie war, ein echter Profi.'::text,'packte'::text,'packte'::text,'gepackt hat'::text,'Während sie tropisches Obst in eine Tüte packte, blieb die Ananas, wo sie war, ein echter Profi.'::text),
(398770,44308,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Поки вона ... тропічні фрукти в пакет, ананас лишився на місці, справжній професіонал.'::text,'клала'::text,'поклала'::text,'поклала'::text,'Поки вона клала тропічні фрукти в пакет, ананас лишився на місці, справжній професіонал.'::text),
(398769,44308,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mientras ... fruta tropical en una bolsa, la piña se quedó quieta, toda una profesional.'::text,'metía'::text,'metió'::text,'ha metido'::text,'Mientras metía fruta tropical en una bolsa, la piña se quedó quieta, toda una profesional.'::text),
(398768,44308,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Pendant qu''elle ... des fruits tropicaux dans un sac, l''ananas n''a pas bougé, un vrai pro.'::text,'mettait'::text,'a mis'::text,'a mis'::text,'Pendant qu''elle mettait des fruits tropicaux dans un sac, l''ananas n''a pas bougé, un vrai pro.'::text),
(398771,44308,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O tropik meyveleri poşete ..., ananas yerinden kıpırdamadı, tam bir profesyonel.'::text,'koyarken'::text,'koydu'::text,'koydu'::text,'O tropik meyveleri poşete koyarken, ananas yerinden kıpırdamadı, tam bir profesyonel.'::text),
(398772,44308,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Miközben trópusi gyümölcsöt ... egy zacskóba, az ananász a helyén maradt, igazi profi.'::text,'rakott'::text,'rakott'::text,'rakott'::text,'Miközben trópusi gyümölcsöt rakott egy zacskóba, az ananász a helyén maradt, igazi profi.'::text),
(398775,44309,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... hier seit Jahren tropisches Obst, also ist diese Pyramide offensichtlich ihr erster Versuch.'::text,'verkauft'::text,'verkauft'::text,'verkauft'::text,'Sie verkauft hier seit Jahren tropisches Obst, also ist diese Pyramide offensichtlich ihr erster Versuch.'::text),
(398779,44309,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона ... тут тропічні фрукти роками, тож ця піраміда, очевидно, її перша спроба.'::text,'продає'::text,'продає'::text,'продає'::text,'Вона продає тут тропічні фрукти роками, тож ця піраміда, очевидно, її перша спроба.'::text),
(398778,44309,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hace años que ... fruta tropical aquí, así que esta pirámide es obviamente su primer intento.'::text,'vende'::text,'está vendiendo'::text,'vende'::text,'Hace años que vende fruta tropical aquí, así que esta pirámide es obviamente su primer intento.'::text),
(398777,44309,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle ... des fruits tropicaux ici depuis des années, donc cette pyramide est évidemment son premier essai.'::text,'vend'::text,'vend'::text,'vend'::text,'Elle vend des fruits tropicaux ici depuis des années, donc cette pyramide est évidemment son premier essai.'::text),
(398780,44309,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yıllardır burada tropik meyve ..., yani bu piramit belli ki ilk denemesi.'::text,'satıyor'::text,'satıyor'::text,'satar'::text,'Yıllardır burada tropik meyve satıyor, yani bu piramit belli ki ilk denemesi.'::text),
(398781,44309,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Évek óta ... itt trópusi gyümölcsöt, szóval ez a piramis nyilván az első próbálkozása.'::text,'árul'::text,'árul'::text,'árul'::text,'Évek óta árul itt trópusi gyümölcsöt, szóval ez a piramis nyilván az első próbálkozása.'::text),
(398784,44310,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... eine tropische Mango, als die ganze Pyramide fast einstürzte!'::text,'nahm'::text,'nahm'::text,'hat genommen'::text,'Sie nahm eine tropische Mango, als die ganze Pyramide fast einstürzte!'::text),
(398788,44310,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона ... тропічне манго, коли вся піраміда мало не завалилася!'::text,'брала'::text,'взяла'::text,'взяла'::text,'Вона брала тропічне манго, коли вся піраміда мало не завалилася!'::text),
(398787,44310,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Mientras ... un mango tropical, casi se derrumbó toda la pirámide!'::text,'cogía'::text,'cogió'::text,'ha cogido'::text,'¡Mientras cogía un mango tropical, casi se derrumbó toda la pirámide!'::text),
(398786,44310,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle ... une mangue tropicale quand toute la pyramide a failli s''effondrer !'::text,'prenait'::text,'a pris'::text,'a pris'::text,'Elle prenait une mangue tropicale quand toute la pyramide a failli s''effondrer !'::text),
(398789,44310,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bütün piramit neredeyse çöktüğünde tropik bir mango ...!'::text,'alıyordu'::text,'aldı'::text,'aldı'::text,'Bütün piramit neredeyse çöktüğünde tropik bir mango alıyordu!'::text),
(398790,44310,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Éppen egy trópusi mangót ... fel, amikor majdnem az egész piramis összedőlt!'::text,'vett'::text,'vett'::text,'vett'::text,'Éppen egy trópusi mangót vett fel, amikor majdnem az egész piramis összedőlt!'::text),
(398793,44311,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... den ganzen Tag in der Hitze hinter diesem tropischen Obst, absolute Folter!'::text,'steht'::text,'stand'::text,'steht'::text,'Sie steht den ganzen Tag in der Hitze hinter diesem tropischen Obst, absolute Folter!'::text),
(398797,44311,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона ... за цими тропічними фруктами в спеку цілий день, справжні тортури!'::text,'стоїть'::text,'стояла'::text,'стоїть'::text,'Вона стоїть за цими тропічними фруктами в спеку цілий день, справжні тортури!'::text),
(398796,44311,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Con este calor, ... todo el día detrás de esta fruta tropical, una tortura absoluta!'::text,'lleva de pie'::text,'estuvo de pie'::text,'está de pie'::text,'¡Con este calor, lleva de pie todo el día detrás de esta fruta tropical, una tortura absoluta!'::text),
(398795,44311,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle ... derrière ces fruits tropicaux dans la chaleur toute la journée, une vraie torture !'::text,'est'::text,'est restée'::text,'est'::text,'Elle est derrière ces fruits tropicaux dans la chaleur toute la journée, une vraie torture !'::text),
(398798,44311,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bütün gün sıcakta bu tropik meyvelerin arkasında ..., tam bir işkence!'::text,'duruyor'::text,'durdu'::text,'duruyor'::text,'Bütün gün sıcakta bu tropik meyvelerin arkasında duruyor, tam bir işkence!'::text),
(398799,44311,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Egész nap ... a trópusi gyümölcsök mögött a hőségben, maga a kínzás!'::text,'áll'::text,'állt'::text,'áll'::text,'Egész nap áll a trópusi gyümölcsök mögött a hőségben, maga a kínzás!'::text),
(398802,44312,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mädel, angeblich hatte sie die Pyramide aus tropischem Obst ..., bevor der erste Kunde kam.'::text,'aufgebaut'::text,'aufgebaut'::text,'aufgebaut'::text,'Mädel, angeblich hatte sie die Pyramide aus tropischem Obst aufgebaut, bevor der erste Kunde kam.'::text),
(398806,44312,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, кажуть, вона ... піраміду з тропічних фруктів ще до того, як прийшов перший покупець.'::text,'збудувала'::text,'збудувала'::text,'будує'::text,'Подруго, кажуть, вона збудувала піраміду з тропічних фруктів ще до того, як прийшов перший покупець.'::text),
(398805,44312,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tía, parece que ... la pirámide de fruta tropical antes de que llegara el primer cliente.'::text,'había montado'::text,'ha montado'::text,'monta'::text,'Tía, parece que había montado la pirámide de fruta tropical antes de que llegara el primer cliente.'::text),
(398804,44312,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Meuf, apparemment elle ... la pyramide de fruits tropicaux avant l''arrivée du premier client.'::text,'avait monté'::text,'a monté'::text,'monte'::text,'Meuf, apparemment elle avait monté la pyramide de fruits tropicaux avant l''arrivée du premier client.'::text),
(398807,44312,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, güya ilk müşteri gelmeden tropik meyve piramidini ...'::text,'kurmuştu'::text,'kurdu'::text,'kuruyor'::text,'Kızım, güya ilk müşteri gelmeden tropik meyve piramidini kurmuştu.'::text),
(398808,44312,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, állítólag még az első vevő érkezése előtt ... a trópusi gyümölcspiramist.'::text,'felépítette'::text,'felépítette'::text,'építi'::text,'Csajszi, állítólag még az első vevő érkezése előtt felépítette a trópusi gyümölcspiramist.'::text),
(398811,44313,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Okay, also angeblich ... sie morgen Mittag ihr tropisches Obst auf dem Nachtmarkt.'::text,'verkauft'::text,'verkauft'::text,'verkauft'::text,'Okay, also angeblich verkauft sie morgen Mittag ihr tropisches Obst auf dem Nachtmarkt.'::text),
(398815,44313,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коротше, кажуть, завтра опівдні вона ... свої тропічні фрукти на нічному ринку.'::text,'продаватиме'::text,'продасть'::text,'продає'::text,'Коротше, кажуть, завтра опівдні вона продаватиме свої тропічні фрукти на нічному ринку.'::text),
(398814,44313,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Vale, pues parece que mañana a mediodía ... su fruta tropical en el mercado nocturno.'::text,'estará vendiendo'::text,'venderá'::text,'vende'::text,'Vale, pues parece que mañana a mediodía estará vendiendo su fruta tropical en el mercado nocturno.'::text),
(398813,44313,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ok, donc apparemment demain à midi elle ... ses fruits tropicaux au marché de nuit.'::text,'vendra'::text,'vendra'::text,'vend'::text,'Ok, donc apparemment demain à midi elle vendra ses fruits tropicaux au marché de nuit.'::text),
(398816,44313,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tamam, güya yarın öğlen tropik meyvelerini gece pazarında ...'::text,'satıyor olacakmış'::text,'satacakmış'::text,'satıyormuş'::text,'Tamam, güya yarın öğlen tropik meyvelerini gece pazarında satıyor olacakmış.'::text),
(398817,44313,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oké, szóval állítólag holnap délben az éjszakai piacon ... a trópusi gyümölcseit.'::text,'fogja árulni'::text,'fogja árulni'::text,'árulja'::text,'Oké, szóval állítólag holnap délben az éjszakai piacon fogja árulni a trópusi gyümölcseit.'::text),
(398829,44315,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'In dieser Straße ... nur einen Stand mit tropischem Obst.'::text,'gab es früher'::text,'gab es früher'::text,'war es gewohnt zu geben'::text,'In dieser Straße gab es früher nur einen Stand mit tropischem Obst.'::text),
(398833,44315,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'На цій вулиці ... лише одна ятка з тропічними фруктами.'::text,'раніше була'::text,'колись бувала'::text,'звикла бути'::text,'На цій вулиці раніше була лише одна ятка з тропічними фруктами.'::text),
(398832,44315,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En esta calle ... haber solo un puesto de fruta tropical.'::text,'solía'::text,'solía'::text,'estaba acostumbrado a'::text,'En esta calle solía haber solo un puesto de fruta tropical.'::text),
(398831,44315,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dans cette rue, il n''y ... qu''un seul stand de fruits tropicaux.'::text,'avait autrefois'::text,'avait autrefois'::text,'avait l''habitude d''avoir'::text,'Dans cette rue, il n''y avait autrefois qu''un seul stand de fruits tropicaux.'::text),
(398834,44315,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu sokakta eskiden sadece bir tropik meyve tezgâhı ...'::text,'vardı'::text,'olurdu'::text,'olmaya alışkındı'::text,'Bu sokakta eskiden sadece bir tropik meyve tezgâhı vardı.'::text),
(398835,44315,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ezen az utcán régen csak egy trópusigyümölcs-stand ...'::text,'volt'::text,'volt'::text,'szokott lenni'::text,'Ezen az utcán régen csak egy trópusigyümölcs-stand volt.'::text),
(398838,44316,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Es macht ihr Spaß, den Leuten in ihrer Straße tropisches Obst zu ...'::text,'verkaufen'::text,'verkaufen'::text,'verkaufen'::text,'Es macht ihr Spaß, den Leuten in ihrer Straße tropisches Obst zu verkaufen.'::text),
(398842,44316,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Їй подобається ... тропічні фрукти людям на її вулиці.'::text,'продавати'::text,'продавати'::text,'продавати'::text,'Їй подобається продавати тропічні фрукти людям на її вулиці.'::text),
(398841,44316,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le encanta ... fruta tropical a la gente de su calle.'::text,'vender'::text,'vender'::text,'vender'::text,'Le encanta vender fruta tropical a la gente de su calle.'::text),
(398840,44316,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle aime ... des fruits tropicaux aux gens de sa rue.'::text,'vendre'::text,'vendre'::text,'vendre'::text,'Elle aime vendre des fruits tropicaux aux gens de sa rue.'::text),
(398843,44316,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sokağındaki insanlara tropik meyve ... seviyor.'::text,'satmayı'::text,'satmayı'::text,'satmayı'::text,'Sokağındaki insanlara tropik meyve satmayı seviyor.'::text),
(398844,44316,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Szeret trópusi gyümölcsöt ... az utcája lakóinak.'::text,'árulni'::text,'árulni'::text,'árulni'::text,'Szeret trópusi gyümölcsöt árulni az utcája lakóinak.'::text),
(398847,44317,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gerade ... du tropisches Obst wie ein Profi, ehrlich.'::text,'verkaufst'::text,'verkaufst'::text,'hast verkauft'::text,'Gerade verkaufst du tropisches Obst wie ein Profi, ehrlich.'::text),
(398851,44317,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Просто зараз ти ... тропічні фрукти як профі, чесно.'::text,'продаєш'::text,'продаєш'::text,'продала'::text,'Просто зараз ти продаєш тропічні фрукти як профі, чесно.'::text),
(398850,44317,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ahora mismo ... fruta tropical como una profesional, en serio.'::text,'estás vendiendo'::text,'vendes'::text,'has vendido'::text,'Ahora mismo estás vendiendo fruta tropical como una profesional, en serio.'::text),
(398849,44317,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Là, tout de suite, tu ... des fruits tropicaux comme une pro, franchement.'::text,'vends'::text,'vends'::text,'as vendu'::text,'Là, tout de suite, tu vends des fruits tropicaux comme une pro, franchement.'::text),
(398852,44317,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Şu anda tropik meyveyi bir profesyonel gibi ..., açıkçası.'::text,'satıyorsun'::text,'satarsın'::text,'sattın'::text,'Şu anda tropik meyveyi bir profesyonel gibi satıyorsun, açıkçası.'::text),
(398853,44317,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Most éppen úgy ... a trópusi gyümölcsöt, mint egy profi, őszintén.'::text,'árulod'::text,'árulod'::text,'árultad'::text,'Most éppen úgy árulod a trópusi gyümölcsöt, mint egy profi, őszintén.'::text),
(359112,39902,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, er ... zur Richterin hoch, als sie ihn schuldig sprach, ohne Witz.'::text,'starrte'::text,'starrte'::text,'hat gestarrt'::text,'Bro, er starrte zur Richterin hoch, als sie ihn schuldig sprach, ohne Witz.'::text),
(359116,39902,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, він ... на суддю, коли вона визнала його винним, без брехні.'::text,'дивився'::text,'глянув'::text,'глянув'::text,'Бро, він дивився на суддю, коли вона визнала його винним, без брехні.'::text),
(359115,39902,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, ... a la jueza cuando lo declaró culpable, sin mentir.'::text,'estaba mirando fijamente'::text,'miró fijamente'::text,'ha mirado fijamente'::text,'Bro, estaba mirando fijamente a la jueza cuando lo declaró culpable, sin mentir.'::text),
(359114,39902,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frérot, il ... la juge quand elle l''a déclaré coupable, sans mentir.'::text,'fixait'::text,'a fixé'::text,'a fixé'::text,'Frérot, il fixait la juge quand elle l''a déclaré coupable, sans mentir.'::text),
(359117,39902,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, hâkim onu suçlu bulduğunda yukarıya, hâkime ..., yemin ederim.'::text,'bakıyordu'::text,'baktı'::text,'baktı'::text,'Kanka, hâkim onu suçlu bulduğunda yukarıya, hâkime bakıyordu, yemin ederim.'::text),
(359118,39902,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, ... a bírónőre, amikor bűnösnek találta, komolyan.'::text,'bámult fel'::text,'felbámult'::text,'felbámult'::text,'Tesó, bámult fel a bírónőre, amikor bűnösnek találta, komolyan.'::text),
(359121,39903,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nee, die Geschworenen ... sich die ganze Woche darüber, ob er schuldig ist, und er zittert irgendwie.'::text,'streiten'::text,'streiten'::text,'streiten'::text,'Nee, die Geschworenen streiten sich die ganze Woche darüber, ob er schuldig ist, und er zittert irgendwie.'::text),
(359125,39903,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Не, присяжні ... цілий тиждень, чи він винний, а він трохи тремтить.'::text,'сперечаються'::text,'сперечаються'::text,'сперечаються'::text,'Не, присяжні сперечаються цілий тиждень, чи він винний, а він трохи тремтить.'::text),
(359124,39903,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Qué va, el jurado ... toda la semana sobre si es culpable, y él está medio temblando.'::text,'lleva discutiendo'::text,'está discutiendo'::text,'discute'::text,'Qué va, el jurado lleva discutiendo toda la semana sobre si es culpable, y él está medio temblando.'::text),
(359123,39903,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Non, le jury ... toute la semaine pour savoir s''il est coupable, et il tremble un peu.'::text,'se dispute'::text,'se dispute'::text,'se dispute'::text,'Non, le jury se dispute toute la semaine pour savoir s''il est coupable, et il tremble un peu.'::text),
(359126,39903,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yok, jüri bütün hafta suçlu olup olmadığını ..., o da biraz titriyor.'::text,'tartışıyor'::text,'tartışıyor'::text,'tartışır'::text,'Yok, jüri bütün hafta suçlu olup olmadığını tartışıyor, o da biraz titriyor.'::text),
(359127,39903,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Á, az esküdtszék egész héten azon ..., hogy bűnös-e, ő meg kicsit remeg.'::text,'vitatkozik'::text,'vitatkozik'::text,'vitatkozik'::text,'Á, az esküdtszék egész héten azon vitatkozik, hogy bűnös-e, ő meg kicsit remeg.'::text),
(359130,39904,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Richterin ... das Schuldurteil um 10:15 Uhr vor und ging zum nächsten Tagesordnungspunkt über.'::text,'las'::text,'las'::text,'hat gelesen'::text,'Die Richterin las das Schuldurteil um 10:15 Uhr vor und ging zum nächsten Tagesordnungspunkt über.'::text),
(359134,39904,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Суддя ... обвинувальний вирок о 10:15 і перейшла до наступного пункту порядку денного.'::text,'зачитала'::text,'читала'::text,'зачитала'::text,'Суддя зачитала обвинувальний вирок о 10:15 і перейшла до наступного пункту порядку денного.'::text),
(359133,39904,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La jueza ... el veredicto de culpabilidad a las 10:15 y pasó al siguiente punto del orden del día.'::text,'leyó'::text,'estaba leyendo'::text,'ha leído'::text,'La jueza leyó el veredicto de culpabilidad a las 10:15 y pasó al siguiente punto del orden del día.'::text),
(359132,39904,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La juge ... le verdict de culpabilité à 10 h 15 et est passée au point suivant de l''ordre du jour.'::text,'a lu'::text,'lisait'::text,'a lu'::text,'La juge a lu le verdict de culpabilité à 10 h 15 et est passée au point suivant de l''ordre du jour.'::text),
(359135,39904,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hâkim suçlu kararını saat 10.15''te ... ve gündemdeki bir sonraki maddeye geçti.'::text,'okudu'::text,'okuyordu'::text,'okudu'::text,'Hâkim suçlu kararını saat 10.15''te okudu ve gündemdeki bir sonraki maddeye geçti.'::text),
(359136,39904,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A bírónő 10:15-kor ... a bűnösséget kimondó ítéletet, és áttért a napirend következő pontjára.'::text,'felolvasta'::text,'olvasta'::text,'felolvasta'::text,'A bírónő 10:15-kor felolvasta a bűnösséget kimondó ítéletet, és áttért a napirend következő pontjára.'::text),
(359139,39905,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Gericht hat den Mann schuldig ..., und die Richterin hat gerade mit dem Hammer geschlagen.'::text,'gesprochen'::text,'gesprochen'::text,'gesprochen'::text,'Das Gericht hat den Mann schuldig gesprochen, und die Richterin hat gerade mit dem Hammer geschlagen.'::text),
(359143,39905,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Суд ... чоловіка винним, і суддя щойно вдарила молотком.'::text,'визнав'::text,'визнавав'::text,'визнає'::text,'Суд визнав чоловіка винним, і суддя щойно вдарила молотком.'::text),
(359142,39905,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El tribunal ... culpable al hombre, y la jueza acaba de dar el golpe de mazo.'::text,'ha declarado'::text,'ha estado declarando'::text,'declara'::text,'El tribunal ha declarado culpable al hombre, y la jueza acaba de dar el golpe de mazo.'::text),
(359141,39905,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le tribunal ... l''homme coupable, et la juge vient de frapper du marteau.'::text,'a déclaré'::text,'a déclaré'::text,'déclare'::text,'Le tribunal a déclaré l''homme coupable, et la juge vient de frapper du marteau.'::text),
(359144,39905,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mahkeme adamı suçlu ... ve hâkim az önce tokmağı vurdu.'::text,'buldu'::text,'buluyordu'::text,'buluyor'::text,'Mahkeme adamı suçlu buldu ve hâkim az önce tokmağı vurdu.'::text),
(359145,39905,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A bíróság bűnösnek ... a férfit, és a bírónő épp most ütött a kalapáccsal.'::text,'mondta ki'::text,'mondta ki'::text,'mondja ki'::text,'A bíróság bűnösnek mondta ki a férfit, és a bírónő épp most ütött a kalapáccsal.'::text),
(359148,39906,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Als die Richterin den Hammer hob, hatte sie ihn schon schuldig ...'::text,'gesprochen'::text,'gesprochen'::text,'gesprochen'::text,'Als die Richterin den Hammer hob, hatte sie ihn schon schuldig gesprochen.'::text),
(359152,39906,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коли суддя підняла молоток, вона вже ... його винним.'::text,'визнала'::text,'визнала'::text,'визнає'::text,'Коли суддя підняла молоток, вона вже визнала його винним.'::text),
(359151,39906,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cuando la jueza levantó el mazo, ya lo ... culpable.'::text,'había declarado'::text,'ha declarado'::text,'declara'::text,'Cuando la jueza levantó el mazo, ya lo había declarado culpable.'::text),
(359150,39906,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Quand la juge a levé le marteau, elle ... coupable.'::text,'l''avait déclaré'::text,'l''a déclaré'::text,'le déclare'::text,'Quand la juge a levé le marteau, elle l''avait déclaré coupable.'::text),
(359153,39906,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hâkim tokmağı kaldırdığında onu çoktan suçlu ...'::text,'bulmuştu'::text,'buldu'::text,'buluyor'::text,'Hâkim tokmağı kaldırdığında onu çoktan suçlu bulmuştu.'::text),
(359154,39906,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mire a bírónő felemelte a kalapácsot, már bűnösnek ... őt.'::text,'mondta ki'::text,'mondta ki'::text,'mondja ki'::text,'Mire a bírónő felemelte a kalapácsot, már bűnösnek mondta ki őt.'::text),
(359157,39907,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nächste Woche um diese Zeit ... der schuldige Mann seine Strafe im Gefängnis ab.'::text,'sitzt'::text,'sitzt'::text,'sitzt'::text,'Nächste Woche um diese Zeit sitzt der schuldige Mann seine Strafe im Gefängnis ab.'::text),
(359161,39907,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Наступного тижня о цій порі винний чоловік ... свій термін у в''язниці.'::text,'відбуватиме'::text,'відбуде'::text,'відбуває'::text,'Наступного тижня о цій порі винний чоловік відбуватиме свій термін у в''язниці.'::text),
(359160,39907,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La semana que viene a esta hora, el hombre culpable ... su condena en prisión.'::text,'estará cumpliendo'::text,'cumplirá'::text,'cumple'::text,'La semana que viene a esta hora, el hombre culpable estará cumpliendo su condena en prisión.'::text),
(359159,39907,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La semaine prochaine à cette heure-ci, l''homme coupable ... sa peine en prison.'::text,'purgera'::text,'purgera'::text,'purge'::text,'La semaine prochaine à cette heure-ci, l''homme coupable purgera sa peine en prison.'::text),
(359162,39907,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gelecek hafta bu saatte suçlu adam cezasını hapiste ...'::text,'çekiyor olacak'::text,'çekecek'::text,'çekiyor'::text,'Gelecek hafta bu saatte suçlu adam cezasını hapiste çekiyor olacak.'::text),
(359163,39907,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Jövő héten ilyenkor a bűnös férfi a börtönben ... a büntetését.'::text,'tölti'::text,'tölti'::text,'tölti'::text,'Jövő héten ilyenkor a bűnös férfi a börtönben tölti a büntetését.'::text),
(359166,39908,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mädel, er schwört, dass er gegen dieses Schuldurteil ...'::text,'kämpfen wird'::text,'kämpfen wird'::text,'kämpft'::text,'Mädel, er schwört, dass er gegen dieses Schuldurteil kämpfen wird.'::text),
(359170,39908,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, він клянеться, що ... проти того обвинувального вироку.'::text,'боротиметься'::text,'боротиметься'::text,'бореться'::text,'Подруго, він клянеться, що боротиметься проти того обвинувального вироку.'::text),
(359169,39908,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tía, jura que ... contra ese veredicto de culpabilidad.'::text,'luchará'::text,'estará luchando'::text,'está luchando'::text,'Tía, jura que luchará contra ese veredicto de culpabilidad.'::text),
(359168,39908,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Meuf, il jure qu''il ... contre ce verdict de culpabilité.'::text,'se battra'::text,'se battra'::text,'se bat'::text,'Meuf, il jure qu''il se battra contre ce verdict de culpabilité.'::text),
(359171,39908,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, o suçlu kararına karşı ... yemin ediyor.'::text,'savaşacağına'::text,'savaşıyor olacağına'::text,'savaştığına'::text,'Kızım, o suçlu kararına karşı savaşacağına yemin ediyor.'::text),
(359172,39908,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, esküszik, hogy ... a bűnösséget kimondó ítélet ellen.'::text,'harcolni fog'::text,'harcolni fog'::text,'harcol'::text,'Csajszi, esküszik, hogy harcolni fog a bűnösséget kimondó ítélet ellen.'::text),
(359184,39910,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ich lüg nicht, wenn du ihn mit dieser ruhigen Stimme schuldig sprichst, ... niemand zu widersprechen.'::text,'wagt'::text,'würde wagen'::text,'wagte'::text,'Ich lüg nicht, wenn du ihn mit dieser ruhigen Stimme schuldig sprichst, wagt niemand zu widersprechen.'::text),
(359188,39910,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Не брехатиму, якщо ти визнаєш його винним цим спокійним голосом, ніхто не ... заперечити.'::text,'наважиться'::text,'наважився б'::text,'наважився'::text,'Не брехатиму, якщо ти визнаєш його винним цим спокійним голосом, ніхто не наважиться заперечити.'::text),
(359187,39910,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'No voy a mentir, si lo declaras culpable con esa voz tan tranquila, nadie se ... a discutir.'::text,'atreverá'::text,'atrevería'::text,'atrevió'::text,'No voy a mentir, si lo declaras culpable con esa voz tan tranquila, nadie se atreverá a discutir.'::text),
(359186,39910,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Je vais pas mentir, si tu le déclares coupable avec cette voix calme, personne n''... contester.'::text,'osera'::text,'oserait'::text,'a osé'::text,'Je vais pas mentir, si tu le déclares coupable avec cette voix calme, personne n''osera contester.'::text),
(359189,39910,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yalan yok, onu o sakin sesinle suçlu bulursan kimse itiraz etmeye ...'::text,'cesaret edemeyecek'::text,'cesaret edemezdi'::text,'cesaret edemedi'::text,'Yalan yok, onu o sakin sesinle suçlu bulursan kimse itiraz etmeye cesaret edemeyecek.'::text),
(359190,39910,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nem hazudok, ha azzal a nyugodt hangoddal mondod ki a bűnösségét, senki sem ... vitatkozni.'::text,'mer majd'::text,'merne'::text,'mert'::text,'Nem hazudok, ha azzal a nyugodt hangoddal mondod ki a bűnösségét, senki sem mer majd vitatkozni.'::text),
(359202,39912,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Perfekter Plan: Er ... sich sicher gewesen, dass man ihn nie schuldig sprechen würde, und dann fiel der Hammer.'::text,'war'::text,'ist'::text,'war gerade'::text,'Perfekter Plan: Er war sich sicher gewesen, dass man ihn nie schuldig sprechen würde, und dann fiel der Hammer.'::text),
(359206,39912,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бездоганний план: він ... впевнений, що його ніколи не визнають винним, а потім упав молоток.'::text,'був'::text,'є'::text,'був'::text,'Бездоганний план: він був впевнений, що його ніколи не визнають винним, а потім упав молоток.'::text),
(359205,39912,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Plan perfecto: ... seguro de que nunca lo declararían culpable, y entonces cayó el mazo.'::text,'había estado'::text,'ha estado'::text,'estaba siendo'::text,'Plan perfecto: había estado seguro de que nunca lo declararían culpable, y entonces cayó el mazo.'::text),
(359204,39912,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Plan parfait : il ... sûr qu''on ne le déclarerait jamais coupable, et puis le marteau est tombé.'::text,'avait été'::text,'a été'::text,'était'::text,'Plan parfait : il avait été sûr qu''on ne le déclarerait jamais coupable, et puis le marteau est tombé.'::text),
(359207,39912,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kusursuz plan: asla suçlu bulunmayacağından ..., sonra tokmak indi.'::text,'emin olmuştu'::text,'emin oldu'::text,'emin oluyordu'::text,'Kusursuz plan: asla suçlu bulunmayacağından emin olmuştu, sonra tokmak indi.'::text),
(359208,39912,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hibátlan terv: ... biztos benne, hogy sosem mondják ki bűnösnek, aztán lecsapott a kalapács.'::text,'volt'::text,'volt'::text,'éppen volt'::text,'Hibátlan terv: volt biztos benne, hogy sosem mondják ki bűnösnek, aztán lecsapott a kalapács.'::text),
(329178,36576,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis 11:00 Uhr wird der Richter zum ganzen Saal ..., laut Tagesordnung.'::text,'gesprochen haben'::text,'sprechen'::text,'sprechen'::text,'Bis 11:00 Uhr wird der Richter zum ganzen Saal gesprochen haben, laut Tagesordnung.'::text),
(329182,36576,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До 11:00 суддя ... до всієї зали, згідно з порядком денним.'::text,'звернеться'::text,'звернеться'::text,'звертатиметься'::text,'До 11:00 суддя звернеться до всієї зали, згідно з порядком денним.'::text),
(329181,36576,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para las 11:00, el juez ... a toda la sala, según el orden del día.'::text,'se habrá dirigido'::text,'se dirigirá'::text,'se estará dirigiendo'::text,'Para las 11:00, el juez se habrá dirigido a toda la sala, según el orden del día.'::text),
(329180,36576,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''ici 11 h, le juge ... à toute la salle, conformément à l''ordre du jour.'::text,'se sera adressé'::text,'s''adressera'::text,'s''adressera'::text,'D''ici 11 h, le juge se sera adressé à toute la salle, conformément à l''ordre du jour.'::text),
(329183,36576,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Saat 11.00''e kadar yargıç, gündem uyarınca bütün salona ...'::text,'hitap etmiş olacak'::text,'hitap edecek'::text,'hitap ediyor olacak'::text,'Saat 11.00''e kadar yargıç, gündem uyarınca bütün salona hitap etmiş olacak.'::text),
(329184,36576,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'11:00-ra a bíró már ... az egész teremhez, a napirend szerint.'::text,'szólt'::text,'szólni fog'::text,'szólni fog'::text,'11:00-ra a bíró már szólt az egész teremhez, a napirend szerint.'::text),
(329187,36577,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis Mittag wird er schon zwei Stunden lang zum Saal ...'::text,'gesprochen haben'::text,'sprechen'::text,'sprechen'::text,'Bis Mittag wird er schon zwei Stunden lang zum Saal gesprochen haben.'::text),
(329191,36577,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До полудня він ... до зали вже дві години.'::text,'звертатиметься'::text,'звертатиметься'::text,'звернеться'::text,'До полудня він звертатиметься до зали вже дві години.'::text),
(329190,36577,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Al mediodía, ... a la sala durante dos horas.'::text,'se habrá estado dirigiendo'::text,'se estará dirigiendo'::text,'se dirigirá'::text,'Al mediodía, se habrá estado dirigiendo a la sala durante dos horas.'::text),
(329189,36577,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''ici midi, il ... à la salle pendant deux heures.'::text,'aura parlé'::text,'parlera'::text,'parlera'::text,'D''ici midi, il aura parlé à la salle pendant deux heures.'::text),
(329192,36577,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Öğlene kadar salona iki saattir ...'::text,'hitap ediyor olacak'::text,'hitap ediyor olacak'::text,'hitap edecek'::text,'Öğlene kadar salona iki saattir hitap ediyor olacak.'::text),
(329193,36577,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Délre már két órája ... a teremhez.'::text,'beszél'::text,'beszél majd'::text,'beszél majd'::text,'Délre már két órája beszél a teremhez.'::text),
(329196,36578,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hätte der Mann gewartet, ... der Richter ohne Unterbrechung zum Saal gesprochen.'::text,'hätte'::text,'würde'::text,'hat'::text,'Hätte der Mann gewartet, hätte der Richter ohne Unterbrechung zum Saal gesprochen.'::text),
(329200,36578,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби чоловік зачекав, суддя ... до зали без перерви.'::text,'звернувся б'::text,'звернувся б'::text,'звернувся'::text,'Якби чоловік зачекав, суддя звернувся б до зали без перерви.'::text),
(329199,36578,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si el hombre hubiera esperado, el juez se ... a la sala sin interrupción.'::text,'habría dirigido'::text,'dirigiría'::text,'dirigió'::text,'Si el hombre hubiera esperado, el juez se habría dirigido a la sala sin interrupción.'::text),
(329198,36578,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si l''homme avait attendu, le juge se ... à la salle sans interruption.'::text,'serait adressé'::text,'adresserait'::text,'est adressé'::text,'Si l''homme avait attendu, le juge se serait adressé à la salle sans interruption.'::text),
(329201,36578,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Adam bekleseydi yargıç salona kesintisiz ...'::text,'hitap etmiş olurdu'::text,'hitap ederdi'::text,'hitap etti'::text,'Adam bekleseydi yargıç salona kesintisiz hitap etmiş olurdu.'::text),
(329202,36578,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a férfi várt volna, a bíró megszakítás nélkül ... a teremhez.'::text,'szólt volna'::text,'szólna'::text,'szólt'::text,'Ha a férfi várt volna, a bíró megszakítás nélkül szólt volna a teremhez.'::text),
(329205,36579,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hätte der Richter keine Notizen geschrieben, ... er jetzt nicht so ruhig zum Saal sprechen.'::text,'würde'::text,'hätte'::text,'wird'::text,'Hätte der Richter keine Notizen geschrieben, würde er jetzt nicht so ruhig zum Saal sprechen.'::text),
(329209,36579,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби суддя не написав нотаток, він зараз не ... до зали так спокійно.'::text,'звертався б'::text,'звернувся б'::text,'звернеться'::text,'Якби суддя не написав нотаток, він зараз не звертався б до зали так спокійно.'::text),
(329208,36579,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si el juez no hubiera escrito notas, ahora no se ... a la sala con tanta calma.'::text,'estaría dirigiendo'::text,'habría dirigido'::text,'dirigirá'::text,'Si el juez no hubiera escrito notas, ahora no se estaría dirigiendo a la sala con tanta calma.'::text),
(329207,36579,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si le juge n''avait pas écrit de notes, il ... à la salle aussi calmement maintenant.'::text,'ne s''adresserait pas'::text,'ne se serait pas adressé'::text,'ne s''adressera pas'::text,'Si le juge n''avait pas écrit de notes, il ne s''adresserait pas à la salle aussi calmement maintenant.'::text),
(329210,36579,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yargıç not yazmamış olsaydı şimdi salona bu kadar sakin ...'::text,'hitap ediyor olmazdı'::text,'hitap etmiş olmazdı'::text,'hitap etmeyecek'::text,'Yargıç not yazmamış olsaydı şimdi salona bu kadar sakin hitap ediyor olmazdı.'::text),
(329211,36579,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a bíró nem írt volna jegyzeteket, most nem ... ilyen nyugodtan a teremhez.'::text,'beszélne'::text,'beszélt volna'::text,'fog beszélni'::text,'Ha a bíró nem írt volna jegyzeteket, most nem beszélne ilyen nyugodtan a teremhez.'::text),
(329214,36580,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Richter ist dafür bekannt, schon viele Male zum Saal ...'::text,'gesprochen zu haben'::text,'zu sprechen'::text,'sprechend'::text,'Der Richter ist dafür bekannt, schon viele Male zum Saal gesprochen zu haben.'::text),
(329218,36580,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Відомо, що суддя вже багато разів ... до зали.'::text,'звертався'::text,'звертається'::text,'звертаючись'::text,'Відомо, що суддя вже багато разів звертався до зали.'::text),
(329217,36580,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Se sabe que el juez ... a la sala muchas veces antes.'::text,'se ha dirigido'::text,'se dirige'::text,'dirigiéndose'::text,'Se sabe que el juez se ha dirigido a la sala muchas veces antes.'::text),
(329216,36580,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le juge est connu pour ... à la salle de nombreuses fois auparavant.'::text,'s''être adressé'::text,'s''adresser'::text,'s''adressant'::text,'Le juge est connu pour s''être adressé à la salle de nombreuses fois auparavant.'::text),
(329219,36580,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yargıcın daha önce salona pek çok kez ... biliniyor.'::text,'hitap ettiği'::text,'hitap ettiği'::text,'hitap ederek'::text,'Yargıcın daha önce salona pek çok kez hitap ettiği biliniyor.'::text),
(329220,36580,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A bíróról ismert, hogy korábban már sokszor ... a teremhez.'::text,'szólt'::text,'szól'::text,'szólva'::text,'A bíróról ismert, hogy korábban már sokszor szólt a teremhez.'::text),
(329223,36581,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Du hast zugegeben, noch nie vor so einem großen Saal ..., und ehrlich, keiner hätte es gemerkt.'::text,'gesprochen zu haben'::text,'zu sprechen'::text,'gesprochen hast'::text,'Du hast zugegeben, noch nie vor so einem großen Saal gesprochen zu haben, und ehrlich, keiner hätte es gemerkt.'::text),
(329227,36581,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ти визнав, що ... до такої великої зали, і чесно, ніхто б не здогадався.'::text,'ніколи раніше не звертався'::text,'ніколи не звертатися'::text,'ніколи не звертався'::text,'Ти визнав, що ніколи раніше не звертався до такої великої зали, і чесно, ніхто б не здогадався.'::text),
(329226,36581,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Admitiste ... a una sala tan grande antes, y la verdad, nadie lo habría notado.'::text,'no haberte dirigido nunca'::text,'no dirigirte nunca'::text,'nunca te dirigiste'::text,'Admitiste no haberte dirigido nunca a una sala tan grande antes, y la verdad, nadie lo habría notado.'::text),
(329225,36581,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tu as avoué ... à une salle aussi grande avant, et franchement, personne ne l''aurait deviné.'::text,'ne t''être jamais adressé'::text,'ne jamais t''adresser'::text,'ne t''es jamais adressé'::text,'Tu as avoué ne t''être jamais adressé à une salle aussi grande avant, et franchement, personne ne l''aurait deviné.'::text),
(329228,36581,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Daha önce hiç bu kadar büyük bir salona ... itiraf ettin ve açıkçası kimse anlamadı.'::text,'hitap etmediğini'::text,'hitap etmemeyi'::text,'hitap etmedin'::text,'Daha önce hiç bu kadar büyük bir salona hitap etmediğini itiraf ettin ve açıkçası kimse anlamadı.'::text),
(329229,36581,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bevallottad, hogy még ... ekkora teremhez, és őszintén, senki sem vette észre.'::text,'sosem szóltál'::text,'sosem szólni'::text,'sosem szóltál'::text,'Bevallottad, hogy még sosem szóltál ekkora teremhez, és őszintén, senki sem vette észre.'::text),
(329232,36582,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, du ... nicht besser zum Saal sprechen können; diese Notizen waren ikonisch.'::text,'hättest'::text,'solltest'::text,'durftest'::text,'Ehrlich, du hättest nicht besser zum Saal sprechen können; diese Notizen waren ikonisch.'::text),
(329236,36582,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, ти ... звернутися до зали краще; ті нотатки були культові.'::text,'не міг би'::text,'не мав би'::text,'не мусив би'::text,'Чесно, ти не міг би звернутися до зали краще; ті нотатки були культові.'::text),
(329235,36582,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En serio, no ... dirigido mejor a la sala; esas notas eran icónicas.'::text,'podrías haberte'::text,'deberías haberte'::text,'debías haberte'::text,'En serio, no podrías haberte dirigido mejor a la sala; esas notas eran icónicas.'::text),
(329234,36582,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Franchement, tu ... t''adresser mieux à la salle ; ces notes étaient iconiques.'::text,'n''aurais pas pu'::text,'n''aurais pas dû'::text,'ne devais pas'::text,'Franchement, tu n''aurais pas pu t''adresser mieux à la salle ; ces notes étaient iconiques.'::text),
(329237,36582,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası, salona bundan daha iyi ...; o notlar efsaneydi.'::text,'hitap edemezdin'::text,'hitap etmemeliydin'::text,'hitap etmemeliydin'::text,'Açıkçası, salona bundan daha iyi hitap edemezdin; o notlar efsaneydi.'::text),
(329238,36582,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, ... jobban szólni a teremhez; azok a jegyzetek ikonikusak voltak.'::text,'nem tudtál volna'::text,'nem kellett volna'::text,'nem lett volna szabad'::text,'Őszintén, nem tudtál volna jobban szólni a teremhez; azok a jegyzetek ikonikusak voltak.'::text),
(329241,36583,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Selten ... einen Richter mit so spannenden Notizen zu einem Saal sprechen hören.'::text,'habe ich'::text,'ich habe'::text,'hörte ich'::text,'Selten habe ich einen Richter mit so spannenden Notizen zu einem Saal sprechen hören.'::text),
(329245,36583,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Рідко ... суддю, який звертається до зали з такими захопливими нотатками.'::text,'я чув'::text,'я чув'::text,'я чув'::text,'Рідко я чув суддю, який звертається до зали з такими захопливими нотатками.'::text),
(329244,36583,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Pocas veces ... a un juez dirigirse a una sala con notas tan emocionantes.'::text,'he oído'::text,'yo he oído'::text,'oí'::text,'Pocas veces he oído a un juez dirigirse a una sala con notas tan emocionantes.'::text),
(329243,36583,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rarement ... un juge s''adresser à une salle avec des notes aussi palpitantes.'::text,'ai-je entendu'::text,'j''ai entendu'::text,'ai-je entendu'::text,'Rarement ai-je entendu un juge s''adresser à une salle avec des notes aussi palpitantes.'::text),
(329246,36583,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bir yargıcın salona böyle heyecan verici notlarla hitap ettiğini nadiren ...'::text,'duydum'::text,'duydum'::text,'duydum'::text,'Bir yargıcın salona böyle heyecan verici notlarla hitap ettiğini nadiren duydum.'::text),
(329247,36583,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ritkán ... bírót ilyen izgalmas jegyzetekkel a teremhez szólni.'::text,'hallottam'::text,'hallottam'::text,'hallottam'::text,'Ritkán hallottam bírót ilyen izgalmas jegyzetekkel a teremhez szólni.'::text),
(329250,36584,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Richter ließ seine Notizen ..., bevor er zum Saal sprach. Wirklich fesselnd.'::text,'ausdrucken'::text,'ausdrucken'::text,'auszudrucken'::text,'Der Richter ließ seine Notizen ausdrucken, bevor er zum Saal sprach. Wirklich fesselnd.'::text),
(329254,36584,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Суддя дав ... свої нотатки, перш ніж звернувся до зали. Справді захопливо.'::text,'надрукувати'::text,'надрукувати'::text,'надрукувати'::text,'Суддя дав надрукувати свої нотатки, перш ніж звернувся до зали. Справді захопливо.'::text),
(329253,36584,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El juez mandó ... sus notas antes de dirigirse a la sala. Realmente apasionante.'::text,'imprimir'::text,'imprimir'::text,'a imprimir'::text,'El juez mandó imprimir sus notas antes de dirigirse a la sala. Realmente apasionante.'::text),
(329252,36584,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le juge a fait ... ses notes avant de s''adresser à la salle. Vraiment captivant.'::text,'imprimer'::text,'imprimer'::text,'imprimer'::text,'Le juge a fait imprimer ses notes avant de s''adresser à la salle. Vraiment captivant.'::text),
(329255,36584,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yargıç notlarını ..., sonra salona hitap etti. Gerçekten sürükleyici.'::text,'bastırdı'::text,'bastırdı'::text,'bastırdı'::text,'Yargıç notlarını bastırdı, sonra salona hitap etti. Gerçekten sürükleyici.'::text),
(329256,36584,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A bíró ... a jegyzeteit, mielőtt a teremhez szólt. Igazán lebilincselő.'::text,'kinyomtattatta'::text,'kinyomtattatta'::text,'kinyomtattatta'::text,'A bíró kinyomtattatta a jegyzeteit, mielőtt a teremhez szólt. Igazán lebilincselő.'::text),
(329268,36586,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, der Richter, ... Perücke einfach goated aussieht, hat gerade zum ganzen Saal gesprochen.'::text,'dessen'::text,'der'::text,'welcher'::text,'Yo, der Richter, dessen Perücke einfach goated aussieht, hat gerade zum ganzen Saal gesprochen.'::text),
(329272,36586,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Йо, суддя, ... перука виглядає топово, щойно звернувся до всієї зали.'::text,'чия'::text,'який'::text,'котрий'::text,'Йо, суддя, чия перука виглядає топово, щойно звернувся до всієї зали.'::text),
(329271,36586,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, el juez, ... peluca es lo más, acaba de dirigirse a toda la sala.'::text,'cuya'::text,'que'::text,'el cual'::text,'Oye, el juez, cuya peluca es lo más, acaba de dirigirse a toda la sala.'::text),
(329270,36586,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, le juge ... la perruque est trop stylée vient de s''adresser à toute la salle.'::text,'dont'::text,'qui'::text,'lequel'::text,'Yo, le juge dont la perruque est trop stylée vient de s''adresser à toute la salle.'::text),
(329273,36586,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, yargıç, ... peruğu efsane duruyor, az önce bütün salona hitap etti.'::text,'ki onun'::text,'ki'::text,'ki'::text,'Yo, yargıç, ki onun peruğu efsane duruyor, az önce bütün salona hitap etti.'::text),
(329274,36586,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyu, a bíró, ... parókája állati jól néz ki, épp most szólt az egész teremhez.'::text,'akinek a'::text,'aki'::text,'amely'::text,'Figyu, a bíró, akinek a parókája állati jól néz ki, épp most szólt az egész teremhez.'::text),
